local config = {
  ui_story_5066_50660101_1_dialog_content = "Escaleras, armarios, pisos...",
  ui_story_5066_50660101_2_dialog_content = "Uf... Finalmente todos están limpios.",
  ui_story_5066_50660101_3_dialog_content = "Eso significa que debería haber terminado con la limpieza de hoy... ¿verdad?",
  ui_story_5066_50660101_4_dialog_content = "Connolly! ¿Dónde fuiste? ¿Está todo el suelo limpio?",
  ui_story_5066_50660101_5_dialog_content = "¡Ah! ¡Es mi tía!",
  ui_story_5066_50660101_6_dialog_content = "¡Estoy en el sótano! ¡Acabo de terminar aquí abajo!",
  ui_story_5066_50660101_7_dialog_content = "¿En serio? ¡Porque acabo de ver algunas manchas en el pasillo de nuevo!",
  ui_story_5066_50660101_8_dialog_content = "Tenemos invitados importantes estos días y toda la familia está ocupada. ¡No seas un estorbo!",
  ui_story_5066_50660101_9_dialog_content = "Vale... ¡Ahora voy!",
  ui_story_5066_50660101_10_dialog_content = "Este debería ser el lugar...",
  ui_story_5066_50660101_11_dialog_content = "¡Ah! Toda esta área está cubierta de arena por los zapatos de la gente...",
  ui_story_5066_50660101_12_dialog_content = "Necesito limpiar esto de inmediato y dirigirme directamente al ático...",
  ui_story_5066_50660101_13_dialog_content = "De lo contrario... Mi tía me tomará aún más antipatía si ve esto.",
  ui_story_5066_50660101_14_dialog_content = "¡Oye, Connolly!",
  ui_story_5066_50660101_15_dialog_content = "¡Eek—! ¿Eres tú, primo?",
  ui_story_5066_50660101_16_dialog_content = "P-Pero pensé que te habían ascendido a un puesto importante en los Bajíos...",
  ui_story_5066_50660101_17_dialog_content = "Jaja, es sorprendente que aún recuerdes todo esto. En efecto, ahora soy un miembro valioso del Tribunal de Tritones.",
  ui_story_5066_50660101_18_dialog_content = "¿También estás limpiando la sala hoy? ¡Vaya ama de casa, pequeño Connolly!",
  ui_story_5066_50660101_19_dialog_content = "Terminaré pronto... ¡No haré perder más tiempo a todos!",
  ui_story_5066_50660101_20_dialog_content = "¿No vas a asistir al banquete familiar?",
  ui_story_5066_50660101_21_dialog_content = "Yo... yo nunca podría asistir...",
  ui_story_5066_50660101_22_dialog_content = "Durante los banquetes... Mi tía me encierra en el ático o me obliga a salir de la casa...",
  ui_story_5066_50660101_23_dialog_content = "No quiere asustar a nuestros invitados, ya que me veo tan extraño...",
  ui_story_5066_50660101_24_dialog_content = "Qué pena. Tu apariencia es realmente bastante peculiar para un residente de este pueblo submarino.",
  ui_story_5066_50660101_25_dialog_content = "Sin embargo, en mis ojos, esta peculiaridad es una forma de estética.",
  ui_story_5066_50660101_26_dialog_content = "Puedo presentarte un trabajo mejor, donde ya no estarás solo.",
  ui_story_5066_50660101_27_dialog_content = "P-Perdóname, ¡pero debería irme ahora! Mi tía todavía tiene muchas cosas para que yo haga.",
  ui_story_5066_50660101_28_dialog_content = "¡Oye, espera!",
  ui_story_5066_50660101_29_dialog_content = "... ¡Desagradecidos!",
  ui_story_5066_50660101_30_dialog_content = "Ah, gracias a Dios que logré escapar...",
  ui_story_5066_50660101_31_dialog_content = "Parece muy interesado en mí, pero su actitud desagradable realmente me hace sentir incómoda...",
  ui_story_5066_50660101_32_dialog_content = "Incluso si pudiera irme... No sería con él...",
  ui_story_5066_50660101_33_dialog_content = "Sé que me sentiría solo si me fuera por mi cuenta... Pero realmente no me importa estar solo.",
  ui_story_5066_50660101_34_dialog_content = "Honestamente, estar en un lugar sin otras personas me queda perfecto.",
  ui_story_5066_50660101_35_dialog_content = "<color=#e8d9bb>Connolly cree que si nadie la nota, entonces nadie puede odiarla, rechazarla o señalarla con el dedo.</color>",
  ui_story_5066_50660101_36_dialog_content = "¿Quién es esa? Su apariencia es realmente extraña, no se parece en absoluto a un pez. ¿Es ella del pueblo?",
  ui_story_5066_50660101_37_dialog_content = "Su nombre es Connolly, según escuché. Y es adoptada.",
  ui_story_5066_50660101_38_dialog_content = "No tengo idea de qué tipo de peces eran sus padres para tener una hija tan rara.",
  ui_story_5066_50660101_39_dialog_content = "Soy el único que se ve diferente en esta casa...",
  ui_story_5066_50660101_40_dialog_content = "Mamá y papá se han ido... Solo mi tía estaba dispuesta a acogerme...",
  ui_story_5066_50660101_41_dialog_content = "Pero no importa cuánto lo intente para ser parte de esta familia... Simplemente no hay lugar para mí aquí.",
  ui_story_5066_50660101_42_dialog_content = "Aun así, no estoy completamente descontento...",
  ui_story_5066_50660101_43_dialog_content = "Y eso es porque... ¡Todavía tengo mi música! Todavía tengo el instrumento y las partituras que mi mamá me dejó...",
  ui_story_5066_50660101_44_dialog_content = "<color=#e8d9bb>Cuando Connolly se siente sola, toca esas melodías familiares.</color>",
  ui_story_5066_50660101_45_dialog_content = "<color=#e8d9bb>Una marcha alegre en La Mayor, una balada lírica en Si Menor y una sombría sonata en Do Mayor. Estas canciones no son solo sus amigos, sino su salvación.</color>",
  ui_story_5066_50660101_46_dialog_content = "¿Qué canción debería tocar hoy...?",
  ui_story_5066_50660101_47_dialog_content = "Eh...? Este puntaje...",
  ui_story_5066_50660101_48_dialog_content = "¡¿Q-Q-Qué hace esta pieza de música aterradora aquí todavía?!",
  ui_story_5066_50660101_49_dialog_content = "La última vez que lo jugué, ¡sucedió algo extremadamente terrible!",
  ui_story_5066_50660101_50_dialog_content = "Incluso invocó a un monstruo con tentáculos, uno que se llamaba a sí mismo...",
  ui_story_5066_50660101_51_dialog_content = "Soy el <color=#FFB400>Señor del Agua</color>...",
  ui_story_5066_50660101_52_dialog_content = "¡El sellado... antiguo... Señor del Agua!",
  ui_story_5066_50660101_53_dialog_content = "La hija común del agua que sostiene la reliquia sagrada, ¿puedes comprender mis palabras?",
  ui_story_5066_50660101_54_dialog_content = "¿...?",
  ui_story_5066_50660101_55_dialog_content = "¡Aaaaaaaah! ¡E-Es un monstruo!",
  ui_story_5066_50660101_56_dialog_content = "¡Por favor, no me comas!",
  ui_story_5066_50660101_57_dialog_content = "... ¡Nunca consumo seres mortales!",
  ui_story_5066_50660101_58_dialog_content = "Estoy aquí porque tu clarinete no es algo común...",
  ui_story_5066_50660101_59_dialog_content = "Tu música me trajo aquí.",
  ui_story_5066_50660101_60_dialog_content = "Deseo formar un pacto contigo.",
  ui_story_5066_50660101_61_dialog_content = "¿Un... pacto?",
  ui_story_5066_50660101_62_dialog_content = "Sí, el poderoso Aqua Pact! Con el Pact, puedes ser la reina y gobernar todo el mundo submarino!",
  ui_story_5066_50660101_63_dialog_content = "La reina... del mundo submarino...",
  ui_story_5066_50660101_64_dialog_content = "Entonces, todo lo que tienes que hacer es tocar la reliquia sagrada que simboliza nuestro pacto... ¡este mismo clarinete!",
  ui_story_5066_50660101_65_dialog_content = "Mi poder se manifestará, ayudándote a conquistar todos los mares!",
  ui_story_5066_50660101_66_dialog_content = "¡Ya no tendrás que temer nada en el mundo!",
  ui_story_5066_50660101_67_dialog_content = "Ahora, dime, ¿cuál es tu respuesta?",
  ui_story_5066_50660101_68_dialog_content = "... May ¿Puedo negarme, por favor?",
  ui_story_5066_50660101_69_dialog_content = "?",
  ui_story_5066_50660101_70_dialog_content = "¡Ah! Eh, tú sabes... Sobre convertirse en reina y esas cosas...",
  ui_story_5066_50660101_71_dialog_content = "No creo que pueda hacer algo que suene tan difícil o llamativo...",
  ui_story_5066_50660101_72_dialog_content = "M-Mi mayor deseo es que la gente deje de notarme...",
  ui_story_5066_50660101_73_dialog_content = "No quiero ningún problema. Solo quiero escuchar mi música...",
  ui_story_5066_50660101_74_dialog_content = "<size=33>Si tuviera solo uno o dos amigos, o tal vez incluso tres para escuchar música conmigo... Eso sería suficiente...</size>",
  ui_story_5066_50660101_75_dialog_content = "...",
  ui_story_5066_50660101_76_dialog_content = "Ya veo. No estás listo para asumir la responsabilidad del reino submarino.",
  ui_story_5066_50660101_77_dialog_content = "Pero esta partitura es evidencia de nuestro posible pacto.",
  ui_story_5066_50660101_78_dialog_content = "Para llamarme, tócalo con tu clarinete.",
  ui_story_5066_50660101_79_dialog_content = "Solo juégalo... juégalo... juégalo...",
  ui_story_5066_50660101_80_dialog_content = "Pensé que esto era solo el preciado instrumento que mamá me dejó...",
  ui_story_5066_50660101_81_dialog_content = "¿Por qué puede invocar a una criatura tan misteriosa...?",
  ui_story_5066_50660101_82_dialog_content = "No se va a quedar conmigo para siempre... ¿O sí?",
  ui_story_5066_50660101_83_dialog_content = "Juegalo...",
  ui_story_5066_50660101_84_dialog_content = "El pacto...",
  ui_story_5066_50660101_85_dialog_content = "Para invocarme...",
  ui_story_5066_50660101_86_dialog_content = "Ahhhhh... ¡Solo pensarlo me hace escuchar su voz de nuevo!",
  ui_story_5066_50660101_87_dialog_content = "Solo necesito... concentrarme en otra cosa...",
  ui_story_5066_50660101_88_dialog_content = "<color=#e8d9bb>Toc, toc, toc—</color>",
  ui_story_5066_50660101_89_dialog_content = "¿Eh? ¿Quién podría estar buscándome en el ático a esta hora...?",
  ui_story_5066_50660101_90_dialog_content = "Connolly! Nos estamos quedando sin ingredientes en la cocina otra vez! ¡Apúrate y ve a comprar algunos!",
  ui_story_5066_50660101_91_dialog_content = "Oh... ¡De acuerdo! ¡Saldré ahora mismo!",
  ui_story_5066_50660201_1_dialog_content = "Uf... Esto debería evitar que mi tía se enoje demasiado.",
  ui_story_5066_50660201_2_dialog_content = "Aun así, ¿qué está pasando hoy...?",
  ui_story_5066_50660201_3_dialog_content = "¿Ya es hora? ¿Por qué no han venido?",
  ui_story_5066_50660201_4_dialog_content = "Disculpe, perdóname...",
  ui_story_5066_50660201_5_dialog_content = "Boo-hoo... ¿Por qué las calles están tan llenas hoy?",
  ui_story_5066_50660201_6_dialog_content = "Parece que todos salieron a ver algo... ¿Es hoy algún tipo de día festivo especial...?",
  ui_story_5066_50660201_7_dialog_content = "¿Qué dijiste?",
  ui_story_5066_50660201_8_dialog_content = "¿Quieres decir que no lo sabes? ¡Hoy es el día de salida del <color=#FFB400>príncipe</color>! Todos están en las calles, tratando de echar un vistazo al príncipe.",
  ui_story_5066_50660201_9_dialog_content = "Eh, me gustaría ver la cara del tipo que nos cobra impuestos todo el tiempo.",
  ui_story_5066_50660201_10_dialog_content = "... No esperaba encontrarme con esto hoy. Las multitudes como esta me asustan más.",
  ui_story_5066_50660201_11_dialog_content = "Necesito apresurarme a volver en cuanto termine de comprar suministros...",
  ui_story_5066_50660201_12_dialog_content = "¡Es el príncipe! ¡El príncipe está aquí!",
  ui_story_5066_50660201_13_dialog_content = "¡Ja!",
  ui_story_5066_50660201_14_dialog_content = "Ugh, esto es simplemente aburrido, ¡tan, tan aburrido!",
  ui_story_5066_50660201_15_dialog_content = "Qué pueblo tan pésimo. Sería mejor quedarme adentro y nunca salir. ¿Por qué mi papá me dejó este basurero en mal estado?",
  ui_story_5066_50660201_16_dialog_content = "Su Alteza, por favor cálmese.",
  ui_story_5066_50660201_17_dialog_content = "Después de todo, este también es tu territorio y todos están ansiosos por conocerte.",
  ui_story_5066_50660201_18_dialog_content = "Entonces deberían pagar más impuestos... ¡Espera un momento!",
  ui_story_5066_50660201_19_dialog_content = "¡Mira a esta chica! Realmente es única...",
  ui_story_5066_50660201_20_dialog_content = "En serio, ¿realmente existe un pez con un aspecto tan peculiar?",
  ui_story_5066_50660201_21_dialog_content = "Puede que se vea un poco rara, pero como coleccionable, probablemente sea súper valiosa.",
  ui_story_5066_50660201_22_dialog_content = "<size=33>Tsk, ¿qué hace Connolly aquí...? ¿No se supone que debería estar en el ático?</size>",
  ui_story_5066_50660201_23_dialog_content = "<size=33>Pero no esperaba que el príncipe estuviera interesado en ella; esta podría ser una oportunidad rara...</size>",
  ui_story_5066_50660201_24_dialog_content = "Su Alteza, es un poco vergonzoso admitirlo, pero esta chica es en realidad mi hermana.",
  ui_story_5066_50660201_25_dialog_content = "Ella es prácticamente un amuleto en casa. Pero cuando se trata de apariencias únicas, nadie puede superarla.",
  ui_story_5066_50660201_26_dialog_content = "Si te interesa, puedo venderte... ofrecértela ahora mismo.",
  ui_story_5066_50660201_27_dialog_content = "Oh, eso es algo conveniente. Qué considerado de tu parte.",
  ui_story_5066_50660201_28_dialog_content = "Pero primero, voy a echar un vistazo más de cerca para averiguar qué pasa con ella.",
  ui_story_5066_50660201_29_dialog_content = "Ya era hora de que me divirtiera visitando este pueblo de mala muerte. Tengo que aprovecharlo al máximo.",
  ui_story_5066_50660201_30_dialog_content = "Por aquí, Su Alteza. Si necesita ayuda, no dude en dar sus órdenes.",
  ui_story_5066_50660201_31_dialog_content = "¡La tripulación del príncipe está en marcha!",
  ui_story_5066_50660201_32_dialog_content = "¿A dónde va? ¡Vamos, sigámoslo y veamos qué pasa!",
  ui_story_5066_50660201_33_dialog_content = "¡Ah—La multitud se está moviendo de nuevo!",
  ui_story_5066_50660201_34_dialog_content = "¡E-E-Espera! Me están empujando hacia afuera...",
  ui_story_5066_50660201_35_dialog_content = "¡Uf!",
  ui_story_5066_50660201_36_dialog_content = "...",
  ui_story_5066_50660201_37_dialog_content = "¿Quién es esta chica? Se atreve a interponerse en el camino del príncipe.",
  ui_story_5066_50660201_38_dialog_content = "¡Guau, se ve tan rara; no parece un pez en absoluto!",
  ui_story_5066_50660201_39_dialog_content = "¡Ay! Oh no... Por favor, dime que mi ropa no se ensució. ¡No tengo suficiente ropa para empezar...",
  ui_story_5066_50660201_40_dialog_content = "¿Por qué siento que todos me están mirando...?",
  ui_story_5066_50660201_41_dialog_content = "¡Oye, tú ahí abajo! Deja de mirar a todos lados, ¡te hablo a ti!",
  ui_story_5066_50660201_42_dialog_content = "¡Eek!",
  ui_story_5066_50660201_43_dialog_content = "Tu apariencia bastante fea ha llamado mi atención.",
  ui_story_5066_50660201_44_dialog_content = "¡Aquí está mi invitación para ti—para convertirte en una pieza preciada de mi colección!",
  ui_story_5066_50660201_45_dialog_content = "Confía en mí, la vida conmigo en las aguas poco profundas es mucho mejor que estar atrapado en este pueblo de mala muerte.",
  ui_story_5066_50660201_46_dialog_content = "Sabes lo que quiero decir, ¿verdad?",
  ui_story_5066_50660201_47_dialog_content = "Um... ¿P-puedo May negarme, por favor?",
  ui_story_5066_50660201_48_dialog_content = "Connolly, ¡no dejes que mi buena voluntad se desperdicie!",
  ui_story_5066_50660201_49_dialog_content = "¡Realmente te he elogiado ante el príncipe para que pudieras tener esta oportunidad!",
  ui_story_5066_50660201_50_dialog_content = "¿Este es el nuevo trabajo del que me hablabas...?",
  ui_story_5066_50660201_51_dialog_content = "Querías... <size=45>¿venderme al príncipe?!</size>",
  ui_story_5066_50660201_52_dialog_content = "No lo hagas sonar tan mal. No es vender; es hacerte un compañero real honorado...",
  ui_story_5066_50660201_53_dialog_content = "Como tu primo, he encontrado el mejor camino para ti.",
  ui_story_5066_50660201_54_dialog_content = "De lo contrario, estarás atrapado en casa haciendo trabajo de sirviente para siempre. ¿No te parece solitario?",
  ui_story_5066_50660201_55_dialog_content = "¿Solo? Ya te lo dije antes, no me siento solo. ¡Todo lo que necesito es mi música y mi clarinete!",
  ui_story_5066_50660201_56_dialog_content = "¿Clarinete? ¿Es ese el instrumento extraño en tu mano?",
  ui_story_5066_50660201_57_dialog_content = "¡Vaya, parece ser un artefacto antiguo... bastante inusual!",
  ui_story_5066_50660201_58_dialog_content = "Preséntamelo para echar un vistazo más de cerca.",
  ui_story_5066_50660201_59_dialog_content = "¡Ah! Yo... ¡no puedo dejarte!",
  ui_story_5066_50660201_60_dialog_content = "¡Nadie puede decirme que no bajo el mar! ¡Entrégalo!",
  ui_story_5066_50660201_61_dialog_content = "Pero... Pero mi mamá me lo dejó...",
  ui_story_5066_50660201_62_dialog_content = "¿Mamá? Hablando de eso, con tu apariencia única, tengo bastante curiosidad por saber cómo era tu madre.",
  ui_story_5066_50660201_63_dialog_content = "Si es posible, sería genial si ambos pudieran ser mis coleccionables juntos.",
  ui_story_5066_50660201_64_dialog_content = "¿...?",
  ui_story_5066_50660201_65_dialog_content = "Por favor, no me mire así, Su Alteza. Ella es adoptada; su madre no es la mía...",
  ui_story_5066_50660201_66_dialog_content = "No...",
  ui_story_5066_50660201_67_dialog_content = "¡¿Qué?!",
  ui_story_5066_50660201_68_dialog_content = "¡No permitiré que insultes a mamá de esa manera!",
  ui_story_5066_50660201_69_dialog_content = "¡Ridículo!",
  ui_story_5066_50660201_70_dialog_content = "Bajo estos mares, nadie ha tenido la audacia de hablarme así.",
  ui_story_5066_50660201_71_dialog_content = "Ya que no estás dispuesto a entregarlo... ¡no me culpes por ser grosero!",
  ui_story_5066_50660201_72_dialog_content = "<color=#e8d9bb>El príncipe salta hacia Connolly.</color>",
  ui_story_5066_50660201_73_dialog_content = "No... ¡Aléjate de mí...!",
  ui_story_5066_50660201_74_dialog_content = "<color=#e8d9bb><size=45>¡Golpe—</size></color>",
  ui_story_5066_50660201_75_dialog_content = "<size=45>¡¡¡Ay!!!</size>",
  ui_story_5066_50660201_76_dialog_content = "¡¿...?!",
  ui_story_5066_50660201_77_dialog_content = "...!!!",
  ui_story_5066_50660201_78_dialog_content = "¿Cómo... cómo te atreves a atacarme con un arma?!",
  ui_story_5066_50660201_79_dialog_content = "Ah... lo-lo siento mucho, no fue mi intención hacer eso...",
  ui_story_5066_50660201_80_dialog_content = "P-Pero aún así... <size=30>Esto fue culpa tuya...</size>",
  ui_story_5066_50660201_81_dialog_content = "¿Qué dijiste?... ¡Guardias! ¿Dónde están los guardias?!",
  ui_story_5066_50660201_82_dialog_content = "¡Agarra a esa chica atrevida y deforme para mí!",
  ui_story_5066_50660201_83_dialog_content = "¡¡¡Sí!!!",
  ui_story_5066_50660201_84_dialog_content = "Aaah... Connolly, ¡tú, alborotador! Estamos perdidos...",
  ui_story_5066_50660201_85_dialog_content = "Oh no... Creo que estoy en un gran problema ahora...",
  ui_story_5066_50660201_86_dialog_content = "Estoy acabado si me atrapan, sin duda alguna... ¡Tengo que huir! No me queda otra opción.",
  ui_story_5066_50660201_87_dialog_content = "Perdóname... ¡Por favor, déjame pasar!",
  ui_story_5066_50660201_88_dialog_content = "<color=#e8d9bb>Ella quiere escapar de la multitud, esconderse en un lugar donde nadie pueda encontrarla.</color>",
  ui_story_5066_50660201_89_dialog_content = "<color=#e8d9bb>¿Pero es eso siquiera posible en una bulliciosa calle submarina como esta...?</color>",
  ui_story_5066_50660302_1_dialog_content = "Ugh... ¡Hacer guardia es el trabajo más aburrido del mundo!",
  ui_story_5066_50660302_2_dialog_content = "¿De verdad no hay chicos malos por aquí? No me importaría una buena pelea en este momento.",
  ui_story_5066_50660302_3_dialog_content = "En comparación con pelear... Preferiría mucho más que simplemente estuviéramos juntos en paz...",
  ui_story_5066_50660302_4_dialog_content = "Sí, lo sé. No estaba siendo serio, solo estaba desahogándome.",
  ui_story_5066_50660302_5_dialog_content = "Bien...",
  ui_story_5066_50660302_6_dialog_content = "Aunque tampoco me importaría si Connolly viniera a charlar un rato!",
  ui_story_5066_50660302_7_dialog_content = "Hace tiempo que no la vemos, ¿verdad?",
  ui_story_5066_50660302_8_dialog_content = "Escuché... Su familia espera a algún tipo de invitado importante... Probablemente ha estado ocupada cuidando de la casa.",
  ui_story_5066_50660302_9_dialog_content = "¿Cuidando de la casa?",
  ui_story_5066_50660302_10_dialog_content = "Ugh, si ha estado encerrada en casa todo este tiempo, estoy seguro de que su molesta tía le ha estado haciendo la vida imposible.",
  ui_story_5066_50660302_11_dialog_content = "Si alguna vez tengo la oportunidad, realmente quiero darle un par de golpes por Connolly!",
  ui_story_5066_50660302_12_dialog_content = "Yo... no te detendría de hacer eso.",
  ui_story_5066_50660302_13_dialog_content = "Connolly nos ha estado ayudando con nuestros recados todo este tiempo, pero no hemos tenido la oportunidad de devolverle el favor... Realmente me está empezando a preocupar...",
  ui_story_5066_50660302_14_dialog_content = "¿Yo sé, verdad?",
  ui_story_5066_50660302_15_dialog_content = "Tampoco aceptará dinero por ello. Incluso dice que está agradecida con nosotros...",
  ui_story_5066_50660302_16_dialog_content = "Oh... Realmente no necesito dinero por hacer recados para ti...",
  ui_story_5066_50660302_17_dialog_content = "Estoy... simplemente feliz de salir de la casa de vez en cuando...",
  ui_story_5066_50660302_18_dialog_content = "Después de todo... Mi tía me regañaba la mayoría del tiempo cuando estaba en casa...",
  ui_story_5066_50660302_19_dialog_content = "Entonces, por favor... por favor, llámame si tienes algún recado que necesites que haga!",
  ui_story_5066_50660302_20_dialog_content = "Ella realmente es una buena chica, ¿eh?",
  ui_story_5066_50660302_21_dialog_content = "¡Ella no es nada como esa bruja avara y astuta para la que solíamos trabajar!",
  ui_story_5066_50660302_22_dialog_content = "<size=45>¡Ohhhhhh!</size>",
  ui_story_5066_50660302_23_dialog_content = "¿Qué pasa con todo el ruido? ¿Está pasando algo allá?",
  ui_story_5066_50660302_24_dialog_content = "Sí... Y también parece bastante animado.",
  ui_story_5066_50660302_25_dialog_content = "¡Realmente quiero ir a echar un vistazo! ¿Cuánto tiempo más tenemos que quedarnos aquí de guardia?!",
  ui_story_5066_50660302_26_dialog_content = "Sé cómo te sientes... Pero aún es muy temprano en nuestro turno...",
  ui_story_5066_50660302_27_dialog_content = "De todos modos, este tipo de alboroto es bastante común.",
  ui_story_5066_50660302_28_dialog_content = "Con un rey tan arrogante y un príncipe pomposo, los habitantes del mar han pasado por momentos difíciles.",
  ui_story_5066_50660302_29_dialog_content = "¿Podría ser que el estúpido príncipe fue atacado por residentes enojados? Eso sí que sería interesante.",
  ui_story_5066_50660302_30_dialog_content = "Si algo así realmente sucediera justo frente a mí...",
  ui_story_5066_50660302_31_dialog_content = "Fingiré que no vi nada...",
  ui_story_5066_50660302_32_dialog_content = "¡Aquí!",
  ui_story_5066_50660302_33_dialog_content = "¡Oigan, ustedes dos!",
  ui_story_5066_50660302_34_dialog_content = "¿Los guardias del príncipe?",
  ui_story_5066_50660302_35_dialog_content = "No me digas que tenía razón...",
  ui_story_5066_50660302_36_dialog_content = "¿Has visto a una chica de aspecto peculiar corriendo por aquí, alguien que lleva un clarinete?",
  ui_story_5066_50660302_37_dialog_content = "...",
  ui_story_5066_50660302_38_dialog_content = "(Es Connolly...)",
  ui_story_5066_50660302_39_dialog_content = "(¿Qué quiere el príncipe con ella?)",
  ui_story_5066_50660302_40_dialog_content = "(Sea lo que sea que esté planeando, no podemos dejar que se salga con la suya.)",
  ui_story_5066_50660302_41_dialog_content = "No importa, no espero que la hayan visto. ¡Ustedes dos son miembros del equipo de búsqueda ahora! Comiencen a buscar desde aquí.",
  ui_story_5066_50660302_42_dialog_content = "Eh... May ¿preguntamos qué pasó justo ahora...?",
  ui_story_5066_50660302_43_dialog_content = "¿Qué pasó? Je, esa chica de aspecto peculiar en realidad se atrevió a golpear al príncipe.",
  ui_story_5066_50660302_44_dialog_content = "¡Esto es sin precedentes!",
  ui_story_5066_50660302_45_dialog_content = "¡Se arrepentirá cuando la atrape!",
  ui_story_5066_50660302_46_dialog_content = "<size=33>¡Bien, Connolly! ¡Muy bien hecho!</size>",
  ui_story_5066_50660302_47_dialog_content = "¿Que acabas de decir?",
  ui_story_5066_50660302_48_dialog_content = "Oh, nada, solo que haremos nuestro trabajo lo mejor que podamos.",
  ui_story_5066_50660302_49_dialog_content = "¡Bueno, pues muévanse!",
  ui_story_5066_50660302_50_dialog_content = "¡Sí señor!",
  ui_story_5066_50660302_51_dialog_content = "...",
  ui_story_5066_50660302_52_dialog_content = "Oh, no, Connolly está en grave peligro esta vez.",
  ui_story_5066_50660302_53_dialog_content = "Tienes razón... Necesitamos encontrarla de inmediato...",
  ui_story_5066_50660302_54_dialog_content = "Y tenemos que encontrarla antes que estos guardias, o las cosas empeorarán aún más.",
  ui_story_5066_50660401_1_dialog_content = "Resoplan...",
  ui_story_5066_50660401_2_dialog_content = "Creo... que los perdí...",
  ui_story_5066_50660401_3_dialog_content = "¡Dirígete hacia aquí! ¡Busca!",
  ui_story_5066_50660401_4_dialog_content = "Ah... Oh, no...",
  ui_story_5066_50660401_5_dialog_content = "Si me enrosco y me escondo aquí... No deberían poder encontrarme...",
  ui_story_5066_50660401_6_dialog_content = "Mi corazón... Está latiendo tan rápido... Siento que no puedo respirar...",
  ui_story_5066_50660401_7_dialog_content = "¡Por aquí! ¡Aquí!",
  ui_story_5066_50660401_8_dialog_content = "Ahhh... Por favor, no me encuentren, no me encuentren, no me encuentren...",
  ui_story_5066_50660401_9_dialog_content = "No tenías que correr, ¿verdad?",
  ui_story_5066_50660401_10_dialog_content = "¡¿...?!",
  ui_story_5066_50660401_11_dialog_content = "Haz un pacto conmigo y todos tus problemas desaparecerán.",
  ui_story_5066_50660401_12_dialog_content = "Tú, es hora de tomar una decisión...",
  ui_story_5066_50660401_13_dialog_content = "Pero.",
  ui_story_5066_50660401_14_dialog_content = "Las cosas ya están así; ¿qué hay para dudar?",
  ui_story_5066_50660401_15_dialog_content = "Yo sé... Pero...",
  ui_story_5066_50660401_16_dialog_content = "<size=33>La idea de... involucrarme con una criatura tan extraña...</size>",
  ui_story_5066_50660401_17_dialog_content = "<size=33>No suena muy agradable tampoco...</size>",
  ui_story_5066_50660401_18_dialog_content = "Alto y claro, escuché tus palabras.",
  ui_story_5066_50660401_19_dialog_content = "Ah... ¡Lo siento! Yo... No quise decirlo de esa manera...",
  ui_story_5066_50660401_20_dialog_content = "¡Los guardias fueron por allí! ¡Vamos a revisar las cosas por aquí!",
  ui_story_5066_50660401_21_dialog_content = "Correcto. Puedo sentirlo... Ella está cerca...",
  ui_story_5066_50660401_22_dialog_content = "...",
  ui_story_5066_50660401_23_dialog_content = "¡Oh no, pasé demasiado tiempo hablando con esa voz...",
  ui_story_5066_50660401_24_dialog_content = "Olvidé por completo el peligro que me rodeaba...",
  ui_story_5066_50660401_25_dialog_content = "*Sniff* ¿D-De verdad tengo que formar parte de la colección del príncipe...?",
  ui_story_5066_50660401_26_dialog_content = "¡Es Connolly! ¡Por fin la encontramos!",
  ui_story_5066_50660401_27_dialog_content = "Uf... Gracias a Dios... Llegamos a ella antes que esos tipos...",
  ui_story_5066_50660401_28_dialog_content = "¿Eh...?",
  ui_story_5066_50660401_29_dialog_content = "¿Estás bien, Connolly? No te lastimaron, ¿verdad?",
  ui_story_5066_50660401_30_dialog_content = "E-Eres tú, Dayna... ¿Y también Robyn?",
  ui_story_5066_50660401_31_dialog_content = "... *asiente*",
  ui_story_5066_50660401_32_dialog_content = "¡Oh, es tan agradable verlos a ambos! Pero lo siento... Realmente no tengo tiempo para ayudar con sus recados hoy...",
  ui_story_5066_50660401_33_dialog_content = "Ahora no es el momento para eso, Connolly.",
  ui_story_5066_50660401_34_dialog_content = "¡Tenemos que salir de aquí antes de que los guardias del príncipe te encuentren!",
  ui_story_5066_50660401_35_dialog_content = "¿Cómo sabes sobre el príncipe? Oh no... ¿No me digas que este lugar tampoco es seguro?",
  ui_story_5066_50660401_36_dialog_content = "Si me encuentran aquí... ¿Q-Qué debo hacer...?",
  ui_story_5066_50660401_37_dialog_content = "No te preocupes... Dayna tuvo una buena idea...",
  ui_story_5066_50660401_38_dialog_content = "¿D... De verdad?",
  ui_story_5066_50660401_39_dialog_content = "¡Sí! Vamos a esperar a que lleguen esos guardias, luego les daremos información incorrecta y los enviaremos a buscar en otro lugar.",
  ui_story_5066_50660401_40_dialog_content = "Eso debería darte tiempo suficiente para encontrar un lugar seguro donde esconderte.",
  ui_story_5066_50660401_41_dialog_content = "Ah... Muchas gracias, pero... No sé cómo pagarles a ustedes dos...",
  ui_story_5066_50660401_42_dialog_content = "Tch, no tiene mucho sentido decir eso, ¿verdad?",
  ui_story_5066_50660401_43_dialog_content = "Nos has estado ayudando durante mucho tiempo... Somos nosotros los que no te hemos recompensado...",
  ui_story_5066_50660401_44_dialog_content = "Pero...",
  ui_story_5066_50660401_45_dialog_content = "Está bien, está bien, guárdalo para otro momento. Perderás tu oportunidad si no te pones en marcha.",
  ui_story_5066_50660401_46_dialog_content = "Ahora vete... Y no mires atrás...",
  ui_story_5066_50660401_47_dialog_content = "¡Lo tengo!",
  ui_story_5066_50660401_48_dialog_content = "¡Apresúrense, grupo inútil! ¿Por qué siguen holgazaneando aquí?",
  ui_story_5066_50660401_49_dialog_content = "La información dice que ella está en este callejón, ¿verdad? ¡Si es incorrecto, enfrentarás consecuencias!",
  ui_story_5066_50660401_50_dialog_content = "Je, parece que llegamos demasiado tarde.",
  ui_story_5066_50660401_51_dialog_content = "Entonces... ¿Qué deberíamos hacer, Dayna?",
  ui_story_5066_50660401_52_dialog_content = "Tenemos que bloquear la entrada a ese callejón, para que Connolly tenga suficiente tiempo para escapar.",
  ui_story_5066_50660401_53_dialog_content = "No importa qué, no podemos dejar que pongan sus manos en ella.",
  ui_story_5066_50660401_54_dialog_content = "Cierto.",
  ui_story_5066_50660401_55_dialog_content = "Um... S-Sólo un momento por favor...",
  ui_story_5066_50660401_56_dialog_content = "Estoy... Estoy realmente agradecido por tu ayuda... Honestamente...",
  ui_story_5066_50660401_57_dialog_content = "Pero tú... Realmente no tienes que ir tan lejos... por alguien como yo...",
  ui_story_5066_50660401_58_dialog_content = "No quiero... causar problemas a ninguno de los dos...",
  ui_story_5066_50660401_59_dialog_content = "No nos hagas parecer extraños, Connolly! ¡Vas a herir nuestros sentimientos!",
  ui_story_5066_50660401_60_dialog_content = "En realidad... Hemos querido... pagar tu amabilidad desde hace mucho tiempo...",
  ui_story_5066_50660401_61_dialog_content = "Sí, pero no nos lo pones fácil, ya que siempre te escondes de todos.",
  ui_story_5066_50660401_62_dialog_content = "A veces me preocupo de que tu tía te haya encerrado y me dan ganas de ir a sacarte de ahí.",
  ui_story_5066_50660401_63_dialog_content = "Entonces por favor... Déjanos ayudarte esta vez...",
  ui_story_5066_50660401_64_dialog_content = "Iré a la izquierda y tú a la derecha. Vamos, Robyn.",
  ui_story_5066_50660401_65_dialog_content = "Vale, Dayna.",
  ui_story_5066_50660402_1_dialog_content = "¿Lo hice... Logré escapar...?",
  ui_story_5066_50660402_2_dialog_content = "Gracias, Dayna y Robyn...",
  ui_story_5066_50660402_3_dialog_content = "...",
  ui_story_5066_50660402_4_dialog_content = "Por su bien, yo... ¡No puedo permitir que me capturen!",
  ui_story_5066_50660402_5_dialog_content = "*resoplando* Yo... creo que debería estar a salvo aquí...",
  ui_story_5066_50660402_6_dialog_content = "...",
  ui_story_5066_50660402_7_dialog_content = "Ah...",
  ui_story_5066_50660402_8_dialog_content = "¿Un guardia que pasa? Parece que... no me ha notado...",
  ui_story_5066_50660402_9_dialog_content = "Aun así... El rey y el príncipe controlan toda esta área... ¿Dónde podría esconderme por aquí?",
  ui_story_5066_50660402_10_dialog_content = "Por mucho que no lo soportaba... ni siquiera puedo volver al ático en la casa de mi tía...",
  ui_story_5066_50660402_11_dialog_content = "Mi prima simplemente encontrará la manera de presentarme al príncipe...",
  ui_story_5066_50660402_12_dialog_content = "...",
  ui_story_5066_50660402_13_dialog_content = "No soy lo suficientemente fuerte como para enfrentarlos a todos yo solo...",
  ui_story_5066_50660402_14_dialog_content = "Lo que significa... Solo me queda una opción, ¿verdad...?",
  ui_story_5066_50660402_15_dialog_content = "Para llamarme, tócalo con tu clarinete.",
  ui_story_5066_50660402_16_dialog_content = "Realmente estoy a punto de jugar... Todavía estoy tan nervioso...",
  ui_story_5066_50660402_17_dialog_content = "Pero después de todo, mamá me dejó este clarinete...",
  ui_story_5066_50660402_18_dialog_content = "Tengo que... ser valiente...",
  ui_story_5066_50660402_19_dialog_content = "*toca el clarinete*",
  ui_story_5066_50660402_20_dialog_content = "...",
  ui_story_5066_50660402_21_dialog_content = "Me alegra ver que finalmente tomas una decisión...",
  ui_story_5066_50660402_22_dialog_content = "¡Ven y haz un pacto conmigo ahora!",
  ui_story_5066_50660402_23_dialog_content = "P-Podría tener un segundo...?",
  ui_story_5066_50660402_24_dialog_content = "En este punto, no hay vuelta atrás para ti.",
  ui_story_5066_50660402_25_dialog_content = "Yo... no me arrepentiré de nada, pero... solo quiero asegurarme de algo primero.",
  ui_story_5066_50660402_26_dialog_content = "No vas a... hacer que haga algo terrible, ¿verdad?",
  ui_story_5066_50660402_27_dialog_content = "Mi objetivo final es que tú seas la reina, gobernando todo el reino submarino.",
  ui_story_5066_50660402_28_dialog_content = "Terrible o no, todo depende de tu propia elección.",
  ui_story_5066_50660402_29_dialog_content = "Pero... Si me convierto en reina o algo así... ¿No me destacaré demasiado?",
  ui_story_5066_50660402_30_dialog_content = "Solo... no quiero hacer algo demasiado llamativo...",
  ui_story_5066_50660402_31_dialog_content = "Una petición extraña... Pensé que si alguien pudiera aprovechar mi poder, querrían mostrar su fuerza al mundo.",
  ui_story_5066_50660402_32_dialog_content = "Pero tú... Bueno, no es gran cosa; definitivamente puedes ser una reina de bajo perfil si eso es lo que quieres.",
  ui_story_5066_50660402_33_dialog_content = "V-Vale entonces. Adelante y... toma el precio que quieras de mí...",
  ui_story_5066_50660402_34_dialog_content = "¿Precio?",
  ui_story_5066_50660402_35_dialog_content = "¿No vas a llevar mis ojos o mi nariz? ... ¿O tal vez quieres mis orejas?",
  ui_story_5066_50660402_36_dialog_content = "*sollozando* No me importa si tienes que comerme... Mientras pueda salir de esta situación peligrosa...",
  ui_story_5066_50660402_37_dialog_content = "Lo he dicho antes... ¡Nunca consumo seres mortales!",
  ui_story_5066_50660402_38_dialog_content = "Boo-hoo! ¡Lo siento! ¡Me olvidé por completo...!",
  ui_story_5066_50660402_39_dialog_content = "No necesitas pagar ningún precio.",
  ui_story_5066_50660402_40_dialog_content = "Hacer un pacto contigo es solo debido a tu singularidad y la reliquia que posees.",
  ui_story_5066_50660402_41_dialog_content = "Cuando se toque la partitura del clarinete, te ayudaré a gobernar los mares.",
  ui_story_5066_50660402_42_dialog_content = "Dicho esto, ¿te quedan dudas en tu mente?",
  ui_story_5066_50660402_43_dialog_content = "Oh... Supongo que no...",
  ui_story_5066_50660402_44_dialog_content = "Pero, ¿no es esto... demasiado bueno para ser verdad...?",
  ui_story_5066_50660402_45_dialog_content = "No te preocupes; estás a punto de comenzar un nuevo capítulo en tu vida. Disfrútalo al máximo.",
  ui_story_5066_50660402_46_dialog_content = "<size=45>¡En este momento, el pacto se hace formalmente!</size>",
  ui_story_5066_50660402_47_dialog_content = "...",
  ui_story_5066_50660501_1_dialog_content = "<color=#e8d9bb>Clang—Clang—</color>",
  ui_story_5066_50660501_2_dialog_content = "Estos guardias son más resistentes de lo que pensaba.",
  ui_story_5066_50660501_3_dialog_content = "¡Atragántense con algas, idiotas!",
  ui_story_5066_50660501_4_dialog_content = "<color=#e8d9bb>Clang—Crujido—</color>",
  ui_story_5066_50660501_5_dialog_content = "No estás equivocado... Son bastante persistentes...",
  ui_story_5066_50660501_6_dialog_content = "Pero no podemos dejar que nos pasen...",
  ui_story_5066_50660501_7_dialog_content = "Vaya, eso es bastante sorprendente.",
  ui_story_5066_50660501_8_dialog_content = "¿En estas aguas, realmente hay quienes se atreven a desafiarme a mí y a mis guardias!?",
  ui_story_5066_50660501_9_dialog_content = "¡Parece que mi visita aquí hoy está bien programada!",
  ui_story_5066_50660501_10_dialog_content = "Si dejamos pasar esto, ¿quién sabe qué tipo de problemas podrían surgir?",
  ui_story_5066_50660501_11_dialog_content = "Guardias, ¿están muriendo de hambre o algo así? ¡Apresúrense y atrapen a estos dos traidores!",
  ui_story_5066_50660501_12_dialog_content = "<color=#e8d9bb>Clang—Crujido—</color>",
  ui_story_5066_50660501_13_dialog_content = "¡Estás mil años adelantado para desafiarme!",
  ui_story_5066_50660501_14_dialog_content = "Pero estaba un poco aburrido, ¡así que divirtámonos!",
  ui_story_5066_50660501_15_dialog_content = "<color=#e8d9bb>Clang—Crujido—</color>",
  ui_story_5066_50660501_16_dialog_content = "Pelear... Realmente no es un problema para nosotros...",
  ui_story_5066_50660501_17_dialog_content = "Ojalá supiera cómo está Connolly en este momento...",
  ui_story_5066_50660501_18_dialog_content = "<color=#e8d9bb>El sonido de un clarinete resuena.</color>",
  ui_story_5066_50660501_19_dialog_content = "¿Qué pasa con esta melodía escalofriante?",
  ui_story_5066_50660501_20_dialog_content = "Oye, guardias, vayan a investigar...",
  ui_story_5066_50660501_21_dialog_content = "...",
  ui_story_5066_50660501_22_dialog_content = "<size=45>¿Qué... qué es esto?!</size>",
  ui_story_5066_50660501_23_dialog_content = "¿Es esa Connolly? ¿Qué le pasó?!",
  ui_story_5066_50660501_24_dialog_content = "Parece que... Ella obtuvo nuevos poderes... ¿Lo hizo solo para ayudarnos?",
  ui_story_5066_50660501_25_dialog_content = "¡Ja! Todo farol; solo parece aterrador.",
  ui_story_5066_50660501_26_dialog_content = "En realidad, me ahorró problemas. ¡Vamos, guardias, vayan a buscarla!",
  ui_story_5066_50660501_27_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660501_28_dialog_content = "Eh... ¡Aaaaah... qué son estos tentáculos?!",
  ui_story_5066_50660501_29_dialog_content = "¡No! ¡Por favor! ¡Bájame!",
  ui_story_5066_50660501_30_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660501_31_dialog_content = "No tengo intención de hacerlo... Solo sigo las órdenes del príncipe... ¡Por favor, perdóname!",
  ui_story_5066_50660501_32_dialog_content = "¡Tampoco quiero pelear contigo! Es... es todo por culpa del príncipe. ¡Él me obligó a hacerlo!",
  ui_story_5066_50660501_33_dialog_content = "¡Alto! ¿¡Quién dijo que podían escapar?! ¡Banda inútil, deténganse! Maldita sea...",
  ui_story_5066_50660501_34_dialog_content = "...",
  ui_story_5066_50660501_35_dialog_content = "Je, je. Bien, muy bien...",
  ui_story_5066_50660501_36_dialog_content = "¡Atrévete a desafiarme y sin duda pagarás el precio!",
  ui_story_5066_50660501_37_dialog_content = "De todos modos, los impuestos que paga este pequeño pueblo deteriorado son lamentablemente bajos desde el principio.",
  ui_story_5066_50660501_38_dialog_content = "Si aún no cumples, ¡no veo razón para la existencia de este pueblo!",
  ui_story_5066_50660501_39_dialog_content = "...",
  ui_story_5066_50660501_40_dialog_content = "Oye, tú... chica de aspecto raro, ¡ya basta!",
  ui_story_5066_50660501_41_dialog_content = "Si el príncipe regresa y le dice al rey que envíe un ejército para destruir nuestro pueblo... ¿puedes soportar las consecuencias?",
  ui_story_5066_50660501_42_dialog_content = "Además, ¡el que has ofendido no es otro que el noble Príncipe!",
  ui_story_5066_50660501_43_dialog_content = "Tú, con tu humilde estatus, ¿cómo puedes actuar con tanto desprecio?",
  ui_story_5066_50660501_44_dialog_content = "...",
  ui_story_5066_50660501_45_dialog_content = "(Sabía que... destacar así realmente no me queda bien...)",
  ui_story_5066_50660501_46_dialog_content = "(Yo... la regué de nuevo, ¿verdad...?)",
  ui_story_5066_50660501_47_dialog_content = "(Si solo me preocupo por el peligro inmediato... ¿Las consecuencias seguirán siendo tan malas...?)",
  ui_story_5066_50660501_48_dialog_content = "Yo... No quise hacer eso... P-Pero...",
  ui_story_5066_50660501_49_dialog_content = "Oye, Connolly! ¡No tienes que disculparte con estos tontos en absoluto!",
  ui_story_5066_50660501_50_dialog_content = "¿Olvidaste cómo ese pomposo príncipe te atacó? ¿Por qué sigues teniendo miedo de él?!",
  ui_story_5066_50660501_51_dialog_content = "¡Si no cambias, te van a molestar por el resto de tu vida!",
  ui_story_5066_50660501_52_dialog_content = "La tolerancia y el compromiso... solo te llevarán hasta cierto punto...",
  ui_story_5066_50660501_53_dialog_content = "Eso es innegable...",
  ui_story_5066_50660501_54_dialog_content = "¡Así es! Solo mira todas las cosas escandalosas que el príncipe ha hecho en este pequeño pueblo.",
  ui_story_5066_50660501_55_dialog_content = "Si él no quiere gobernar sobre nosotros, ¡por mí está bien!",
  ui_story_5066_50660501_56_dialog_content = "¡Ya es hora de elegir un nuevo gobernante de todos modos!",
  ui_story_5066_50660501_57_dialog_content = "...",
  ui_story_5066_50660501_58_dialog_content = "<size=33>Bueno, creo... que lo que ella dijo en realidad tiene sentido...</size>",
  ui_story_5066_50660501_59_dialog_content = "<size=33>Honestamente, yo también he tenido suficiente...</size>",
  ui_story_5066_50660501_60_dialog_content = "Si vuelven a subir los impuestos, no sobreviviremos; será un callejón sin salida de todos modos.",
  ui_story_5066_50660501_61_dialog_content = "Si es posible, podríamos conseguir un nuevo gobernante, ¿verdad?",
  ui_story_5066_50660501_62_dialog_content = "<size=45>¡Indignante, todos están siendo indignantes!</size>",
  ui_story_5066_50660501_63_dialog_content = "¿Pensar que ustedes, gente humilde, podrían sacudir nuestro reinado con unas pocas palabras? ¡Eso no va a pasar!",
  ui_story_5066_50660501_64_dialog_content = "Hoy, haré un ejemplo y ejecutaré a todos ustedes rebeldes que hablan fuera de turno.",
  ui_story_5066_50660501_65_dialog_content = "Um... Yo soy el que causó todo este lío...",
  ui_story_5066_50660501_66_dialog_content = "Todos hablaban por mí hace un momento...",
  ui_story_5066_50660501_67_dialog_content = "Pero ahora que tengo este increíble poder... Yo... Ya no soy el mismo de antes...",
  ui_story_5066_50660501_68_dialog_content = "Esta vez... ¡Es mi turno de proteger a todos!",
  ui_story_5066_50660602_1_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50660602_2_dialog_content = "Ah... duele...",
  ui_story_5066_50660602_3_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50660602_4_dialog_content = "¡Eek... no, por favor, alto!",
  ui_story_5066_50660602_5_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660602_6_dialog_content = "Basta... ¡Eso es suficiente!",
  ui_story_5066_50660602_7_dialog_content = "¡Perdí! ¡Me rindo! No... no perdí contra ti...",
  ui_story_5066_50660602_8_dialog_content = "¡Perdí contra este monstruo de tentáculos!",
  ui_story_5066_50660602_9_dialog_content = "¡¿De dónde diablos adquiriste tal poder?!",
  ui_story_5066_50660602_10_dialog_content = "Bueno... eh, no sé cómo explicar esto...",
  ui_story_5066_50660602_11_dialog_content = "¿Quizás sería mejor que lo vean ustedes mismos?",
  ui_story_5066_50660602_12_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660602_13_dialog_content = "...",
  ui_story_5066_50660602_14_dialog_content = "¡¿...?!",
  ui_story_5066_50660602_15_dialog_content = "¡¿Qué?! ¡Es...!",
  ui_story_5066_50660602_16_dialog_content = "¿Podría ser... el templo del que habla la antigua leyenda...?",
  ui_story_5066_50660602_17_dialog_content = "No, no, no, ¡absolutamente imposible! ¿Cómo podría esta chica de aspecto peculiar...",
  ui_story_5066_50660602_18_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50660602_19_dialog_content = "<color=#e8d9bb>¡Sploosh—!</color>",
  ui_story_5066_50660602_20_dialog_content = "Ugh... Urgh...",
  ui_story_5066_50660602_21_dialog_content = "¿Cómo te atreves...? ¿Cómo te atreves...? Solo espera, el ejército del reino vendrá aquí... para ajustar cuentas y limpiar mi vergüenza.",
  ui_story_5066_50660602_22_dialog_content = "Uf... Creo que finalmente me ocupé de ellos... ¿verdad?",
  ui_story_5066_50660602_23_dialog_content = "¡Por supuesto que lo hiciste, Connolly! ¡La forma en que hiciste volar al príncipe fue increíble! ¡Ten confianza en ti mismo!",
  ui_story_5066_50660602_24_dialog_content = "Es cierto... Ni siquiera Dayna podría haber hecho algo así...",
  ui_story_5066_50660602_25_dialog_content = "Yo... No fue tan impresionante... Por favor, no se burlen de mí, ustedes dos...",
  ui_story_5066_50660602_26_dialog_content = "No nos estamos burlando de ti en absoluto.",
  ui_story_5066_50660602_27_dialog_content = "Entonces, ¿qué es esa cosa en el mundo, Connolly? ¿Algún tipo de monstruo?",
  ui_story_5066_50660602_28_dialog_content = "Dayna... Eso pudo haber sido... Un poco grosero...",
  ui_story_5066_50660602_29_dialog_content = "¡Vaya, lo siento por eso! Es más como tu amigo, ¿verdad?",
  ui_story_5066_50660602_30_dialog_content = "Uh... Para ser honesto, tampoco sé realmente qué es...",
  ui_story_5066_50660602_31_dialog_content = "Pero se sigue llamando a sí mismo \"el gran Señor del Agua\".",
  ui_story_5066_50660602_32_dialog_content = "Entonces supongo... Debe ser una figura bastante poderosa de algún tipo, ¿verdad?",
  ui_story_5066_50660602_33_dialog_content = "<size=45>¿Señor Aqua? Es el... ¿Señor Aqua?!</size>",
  ui_story_5066_50660602_34_dialog_content = "¿Eh? Perdón... ¿Estás familiarizado con el Señor Aqua?",
  ui_story_5066_50660602_35_dialog_content = "Aqua Lord... ¡Era el gran gobernante que alguna vez dominó el mundo submarino!",
  ui_story_5066_50660602_36_dialog_content = "Antes de que el brutal Rey Tritón llegara a las aguas poco profundas, solía gobernar todo aquí...",
  ui_story_5066_50660602_37_dialog_content = "Se rumorea que hasta el día de hoy, los restos de su templo con poder oculto aún existen.",
  ui_story_5066_50660602_38_dialog_content = "<anim type=Shake>ç åï|'H>■...</anim>",
  ui_story_5066_50660602_39_dialog_content = "Las palabras sagradas, ¡son las palabras sagradas! El Señor está a punto de transmitirnos las palabras sagradas...",
  ui_story_5066_50660602_40_dialog_content = "...",
  ui_story_5066_50660602_41_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_5066_50660602_42_dialog_content = "<color=#e8d9bb>Con una mirada de fe inquebrantable, el anciano se arrodilla en reverencia...</color>",
  ui_story_5066_50660602_43_dialog_content = "<color=#e8d9bb>Como una ola, el resto de los habitantes submarinos comienzan a postrarse ante este gobernante que alguna vez fue grandioso...</color>",
  ui_story_5066_50660701_1_dialog_content = "¡Todo es tu culpa por enviar a Connolly a hacer recados, y ahora se ha convertido en un desastre total!",
  ui_story_5066_50660701_2_dialog_content = "¿Cómo podría haber sabido que ella se atrevería a ser tan imprudente y desafiante?",
  ui_story_5066_50660701_3_dialog_content = "Si esto afecta la carrera de nuestro hijo, de ninguna manera podrás compensarlo.",
  ui_story_5066_50660701_4_dialog_content = "Deja de hablar de eso; ¡solo detente! Esta maldita maldición, una vez que la encontremos, ¡tendremos que darle una buena lección!",
  ui_story_5066_50660701_5_dialog_content = "...",
  ui_story_5066_50660701_6_dialog_content = "¿Qué está pasando? ¿Por qué todos están arrodillados en el suelo?",
  ui_story_5066_50660701_7_dialog_content = "Mira... mira allá.",
  ui_story_5066_50660701_8_dialog_content = "<anim type=Agitar>âŠâ €په؛‹Šèã</anim>",
  ui_story_5066_50660701_9_dialog_content = "Eso es... He oído hablar de ello. ¡Ese es el Gran Señor de los tiempos antiguos!",
  ui_story_5066_50660701_10_dialog_content = "Y junto al señor está... ¿Connolly?! ¿Cómo es eso posible?",
  ui_story_5066_50660701_11_dialog_content = "No te preocupes si es posible o no. ¡Arrodíllate rápido, o seremos nosotros los que estemos en problemas!",
  ui_story_5066_50660701_12_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_5066_50660701_13_dialog_content = "<anim type=Shake>е­‘гдё —пе›Œâ€¦в¦</anim>",
  ui_story_5066_50660701_14_dialog_content = "Aunque había muchas voces diferentes provenientes de la multitud justo ahora...",
  ui_story_5066_50660701_15_dialog_content = "Parece que todos más o menos aceptan a este Señor Aqua.",
  ui_story_5066_50660701_16_dialog_content = "El problema, parece ser... es que nadie puede entender lo que está diciendo.",
  ui_story_5066_50660701_17_dialog_content = "Puede que no lo entendamos, pero no debería ser un problema para Connolly!",
  ui_story_5066_50660701_18_dialog_content = "¿Te importaría traducir para nosotros?",
  ui_story_5066_50660701_19_dialog_content = "Oh... No me di cuenta de que nadie más podía entender...",
  ui_story_5066_50660701_20_dialog_content = "Su discurso tiene el mismo efecto que la melodía de esa partitura de antes...",
  ui_story_5066_50660701_21_dialog_content = "¿Podría ser... por qué me eligió?",
  ui_story_5066_50660701_22_dialog_content = "B-Bueno... Si nadie se opone...",
  ui_story_5066_50660701_23_dialog_content = "Traduciré las palabras del Señor Aqua para que todos las escuchen...",
  ui_story_5066_50660701_24_dialog_content = "<anim type=Agitar>éµè Œâ€...¦â€¦ å“š■</anim>",
  ui_story_5066_50660701_25_dialog_content = "El Señor Aqua dice que desea regresar a este mundo y recuperar esta ciudad del Rey Tritón usurpador.",
  ui_story_5066_50660701_26_dialog_content = "<anim type=Shake>FzI¦م€ ...■چcJ;@ڑ â– é‡Œ</anim>",
  ui_story_5066_50660701_27_dialog_content = "Y... debido a mi habilidad innata para comunicarme con él, el Señor del Agua formó un pacto conmigo...",
  ui_story_5066_50660701_28_dialog_content = "Para servir como su mensajero y cumplir con su voluntad...",
  ui_story_5066_50660701_29_dialog_content = "<anim type=Shake>â€¦â€¦و°i%µç·tu€¦â€i... €¦â€¦وˆگم€■</anim>",
  ui_story_5066_50660701_30_dialog_content = "Eh...?!",
  ui_story_5066_50660701_31_dialog_content = "(Uh-oh...)",
  ui_story_5066_50660701_32_dialog_content = "(¿Quiere que le diga a todos... Que soy el Aqua Queen...?)",
  ui_story_5066_50660701_33_dialog_content = "(No creo... que pueda decir algo así...)",
  ui_story_5066_50660701_34_dialog_content = "(Ya dije... Que no quiero hacer nada que me haga destacar demasiado...)",
  ui_story_5066_50660701_35_dialog_content = "<anim type=Shake>еâ€...eåŸœ■å€âŠâ</anim>",
  ui_story_5066_50660701_36_dialog_content = "<size=33>Ya es suficiente, Señor Aqua... Si haces más exigencias, solo asustarás a todos...</size>",
  ui_story_5066_50660701_37_dialog_content = "... (descontento)",
  ui_story_5066_50660701_38_dialog_content = "Em. Oh...",
  ui_story_5066_50660701_39_dialog_content = "¿Está bien... si dejo de traducir ahora?",
  ui_story_5066_50660701_40_dialog_content = "...",
  ui_story_5066_50660701_41_dialog_content = "Por supuesto, ¡Portavoz de lo Divino! ¿O deberíamos dirigirnos a usted como... el Queen?",
  ui_story_5066_50660701_42_dialog_content = "<size=45>Uhhh... ¿Queen?</size>",
  ui_story_5066_50660701_43_dialog_content = "E-Eso es un poco atrevido, ¿no crees...?",
  ui_story_5066_50660701_44_dialog_content = "<size=33>No traduje ni siquiera esa última parte, pero de alguna manera... Todos ya han comenzado... a llamarme \"reina\"?</size>",
  ui_story_5066_50660701_45_dialog_content = "¡Así es, Su Majestad, su poder es evidente para todos!",
  ui_story_5066_50660701_46_dialog_content = "Esos despreciables guardias tritones están merodeando por aquí. ¡De verdad deberías enseñarles una lección!",
  ui_story_5066_50660701_47_dialog_content = "¡Tienes todo nuestro apoyo!",
  ui_story_5066_50660701_48_dialog_content = "Oh... Bueno, si las cosas van a ser así...",
  ui_story_5066_50660701_49_dialog_content = "Incluso si no lo hacía por el bien de los demás, ni siquiera por el mío propio...",
  ui_story_5066_50660701_50_dialog_content = "Aún quiero terminar de limpiar por aquí...",
  ui_story_5066_50660702_1_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50660702_2_dialog_content = "Uf... Ese fue el último de ellos. Esos guardias tritones deberían haberse ido ya...",
  ui_story_5066_50660702_3_dialog_content = "¡Esos malditos matones deberían haber sido echados del pueblo hace mucho tiempo!",
  ui_story_5066_50660702_4_dialog_content = "Lamentablemente, las galletas de Connolly no llegaron. Qué bajón...",
  ui_story_5066_50660702_5_dialog_content = "Oye Connolly... No pareces especialmente feliz... ¿Está todo bien?",
  ui_story_5066_50660702_6_dialog_content = "¡Oh, lo siento! Podrías decirlo con solo mirar, ¿eh...?",
  ui_story_5066_50660702_7_dialog_content = "Justo ahora... Todos comenzaron a llamarme su reina...",
  ui_story_5066_50660702_8_dialog_content = "Pero... No quiero ser este tipo de reina extraña...",
  ui_story_5066_50660702_9_dialog_content = "Yo... preferiría pasar mis días solo en el ático, con nada más que mi música para hacerme compañía...",
  ui_story_5066_50660702_10_dialog_content = "Realmente no lo entiendo, pero apoyo de todo corazón tu decisión.",
  ui_story_5066_50660702_11_dialog_content = "Pero... El tritón...",
  ui_story_5066_50660702_12_dialog_content = "Está bien, Robyn. No asustes a Connolly.",
  ui_story_5066_50660702_13_dialog_content = "Está bien... Soy consciente de la situación en la que estoy...",
  ui_story_5066_50660702_14_dialog_content = "El Rey Tritón... No me dejará ir tan fácilmente, ¿verdad?",
  ui_story_5066_50660702_15_dialog_content = "...",
  ui_story_5066_50660702_16_dialog_content = "Tsk, ¡no te preocupes! Robyn y yo te protegeremos.",
  ui_story_5066_50660702_17_dialog_content = "Es cierto... Después de todo, siempre has sido tan amable con nosotros.",
  ui_story_5066_50660702_18_dialog_content = "Queríamos pagarte hace un momento, pero terminaste salvándonos de nuevo...",
  ui_story_5066_50660702_19_dialog_content = "Pero... Pero solo estaba cumpliendo con mi deber.",
  ui_story_5066_50660702_20_dialog_content = "El Señor Aqua me ayudó cuando estaba en peligro... Así que tengo que devolverle el favor cumpliendo sus deseos...",
  ui_story_5066_50660702_21_dialog_content = "Después de todo... No me quitó nada cuando formamos nuestro pacto...",
  ui_story_5066_50660702_22_dialog_content = "¿Sus deseos? ¿Quieres decir que vas a ayudarlo a recuperar esta ciudad?!",
  ui_story_5066_50660702_23_dialog_content = "Sí... Entonces, ¿podrías contarme todo lo que sabes sobre el Rey Tritón?",
  ui_story_5066_50660702_24_dialog_content = "¡Por supuesto! Robyn es mejor explicando estas cosas, así que la dejaré hacerlo.",
  ui_story_5066_50660702_25_dialog_content = "Está bien Dayna, pero aún necesitas ayudarme a llenar los vacíos...",
  ui_story_5066_50660702_26_dialog_content = "Supongo que deberíamos empezar desde el principio mismo.",
  ui_story_5066_50660702_27_dialog_content = "El Rey Tritón es... Un hombre altivo que proviene de las Sombras...",
  ui_story_5066_50660702_28_dialog_content = "Y se proclamó a sí mismo gobernante de todos los peces.",
  ui_story_5066_50660702_29_dialog_content = "El tipo es un firme creyente en la supremacía de los Bajíos, así que menosprecia a todas las demás razas que viven en el fondo del océano.",
  ui_story_5066_50660702_30_dialog_content = "Por eso recurre a la crueldad y violencia al gobernar pequeños pueblos como este.",
  ui_story_5066_50660702_31_dialog_content = "También es por eso... Rara vez se muestra por aquí.",
  ui_story_5066_50660702_32_dialog_content = "Por otro lado, el Príncipe Tritón... es su sucesor, así como la persona que él designó para cobrarnos impuestos.",
  ui_story_5066_50660702_33_dialog_content = "Aunque el príncipe parezca un idiota...",
  ui_story_5066_50660702_34_dialog_content = "No podemos olvidar que él es una persona distinguida de Los Bajíos, una zona rica en recursos y tecnología avanzada...",
  ui_story_5066_50660702_35_dialog_content = "No se debe subestimar su astucia y armamento.",
  ui_story_5066_50660702_36_dialog_content = "Lo que también significa que el Rey Tritón es aún más aterrador.",
  ui_story_5066_50660702_37_dialog_content = "¿No acabas de decir que no la asustes...?",
  ui_story_5066_50660702_38_dialog_content = "Quiero decir, si vamos a pelear, entonces realmente no tiene sentido seguir andándonos por las ramas.",
  ui_story_5066_50660702_39_dialog_content = "Bu ju...",
  ui_story_5066_50660702_40_dialog_content = "Yo... Estoy realmente agradecido con ambos por contarme todo esto...",
  ui_story_5066_50660702_41_dialog_content = "Pero... ¿Realmente tengo una oportunidad contra alguien tan poderoso como el Rey Tritón?",
  ui_story_5066_50660702_42_dialog_content = "...",
  ui_story_5066_50660702_43_dialog_content = "No tengas miedo, Connolly. Tú y el Señor Aqua son mucho más fuertes que todos ellos...",
  ui_story_5066_50660702_44_dialog_content = "No solo eso, siempre estaremos a tu lado...",
  ui_story_5066_50660702_45_dialog_content = "¡Así es! Solo esperaremos a que te conviertas en el Queen!",
  ui_story_5066_50660702_46_dialog_content = "¡Y cuando llegue ese día, serviremos como tus guardias reales!",
  ui_story_5066_50660702_47_dialog_content = "Uno a tu izquierda... Y uno a tu derecha.",
  ui_story_5066_50660702_48_dialog_content = "Nunca demasiado lejos de tu lado...",
  ui_story_5066_50660702_49_dialog_content = "Así podemos ayudarte siempre que lo necesites, ¿verdad?",
  ui_story_5066_50660702_50_dialog_content = "¡También te ayudaríamos a recuperar el control de esta ciudad!",
  ui_story_5066_50660702_51_dialog_content = "¡No puedes dejarme fuera si vas a hacer algo genial como eso!",
  ui_story_5066_50660702_52_dialog_content = "Además, hace tiempo que quiero borrar esa mirada arrogante de la cara del rey.",
  ui_story_5066_50660702_53_dialog_content = "Todos... Realmente no sé... Cómo podría pagarles alguna vez...",
  ui_story_5066_50660702_54_dialog_content = "Pero con tu ayuda, sé que no tendría nada que temer.",
  ui_story_5066_50660702_55_dialog_content = "Entonces por favor... ¡Por favor, préstame tu fuerza...!",
  ui_story_5066_50660801_1_dialog_content = "*toca el clarinete*",
  ui_story_5066_50660801_2_dialog_content = "...",
  ui_story_5066_50660801_3_dialog_content = "¡Ay! ... Aunque no es la primera vez que lo invoco, aún no puedo evitar sentir un poco de miedo...",
  ui_story_5066_50660801_4_dialog_content = "Um... P-Perdón por invocarte de nuevo tan pronto...",
  ui_story_5066_50660801_5_dialog_content = "Solo quería decirte... que estoy listo y dispuesto para cumplir tus deseos.",
  ui_story_5066_50660801_6_dialog_content = "Estoy profundamente complacido con tu decisión.",
  ui_story_5066_50660801_7_dialog_content = "Entonces, hagamos oficial este pacto.",
  ui_story_5066_50660801_8_dialog_content = "¿Eh...? Pero pensé que ya habíamos formado nuestro pacto, ¿no?",
  ui_story_5066_50660801_9_dialog_content = "Soy el antiguo... y gran Señor Aqua. Un pacto temporal en el campo de batalla es simplemente una medida de emergencia.",
  ui_story_5066_50660801_10_dialog_content = "No corresponde a mi estimado estatus.",
  ui_story_5066_50660801_11_dialog_content = "Oh... Está bien. Entonces, ¿cómo deberíamos hacerlo...?",
  ui_story_5066_50660801_12_dialog_content = "Con tu clarinete como reliquia, formalicemos esto.",
  ui_story_5066_50660801_13_dialog_content = "De esta manera, siempre puedo estar a tu lado.",
  ui_story_5066_50660801_14_dialog_content = "Entonces, ¿así...?",
  ui_story_5066_50660801_15_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660801_16_dialog_content = "Muy bien, esto constituye el pacto oficial.",
  ui_story_5066_50660801_17_dialog_content = "Siendo el Queen, es tu deber gestionar la ciudad en mi nombre.",
  ui_story_5066_50660801_18_dialog_content = "Oh... haré lo mejor que pueda, aunque nunca haya hecho algo así antes...",
  ui_story_5066_50660801_19_dialog_content = "Además, reconstruir el templo.",
  ui_story_5066_50660801_20_dialog_content = "Para restaurar mi poder y defenderme del próximo ataque del Rey Tritón.",
  ui_story_5066_50660801_21_dialog_content = "Eh... ¿Qué templo?",
  ui_story_5066_50660801_22_dialog_content = "Lo mencioné antes, pero tú... no lo interpretaste.",
  ui_story_5066_50660801_23_dialog_content = "No sé cómo decirlo... parece que vamos a hacer trabajar a todos.",
  ui_story_5066_50660801_24_dialog_content = "Pero... prometo que encontraré una solución...",
  ui_story_5066_50660801_25_dialog_content = "Entonces, eh... ¿Qué tipo de templo quieres?",
  ui_story_5066_50660801_26_dialog_content = "Para honrarme a mí, el gran Señor Aqua, hay requisitos sobre la escala de mi templo, los cuales debes tener en mente.",
  ui_story_5066_50660801_27_dialog_content = "¡Lo tengo!",
  ui_story_5066_50660801_28_dialog_content = "En primer lugar, debe ser tan grandioso como la iglesia donde reside el demonio nocturno.",
  ui_story_5066_50660801_29_dialog_content = "El \"demonio nocturno\"? Hmm... Un gran templo... Ajá, entendido.",
  ui_story_5066_50660801_30_dialog_content = "Debería ser tan misterioso como la Casa de la Bruja...",
  ui_story_5066_50660801_31_dialog_content = "\"Tan misterioso como la casa de una bruja...\"",
  ui_story_5066_50660801_32_dialog_content = "¡Sí, eso debería quedar bastante bien!",
  ui_story_5066_50660801_33_dialog_content = "Debería poseer el encanto antiguo de un castillo herético.",
  ui_story_5066_50660801_34_dialog_content = "¿Un castillo antiguo? Tienes buen gusto en arquitectura, Señor Aqua...",
  ui_story_5066_50660801_35_dialog_content = "Debería brillar en la oscuridad como un Trapezoedro Resplandeciente.",
  ui_story_5066_50660801_36_dialog_content = "Un templo que brilla en la oscuridad... Suena como algo sacado de un cuento de hadas, pero me gusta esa idea...",
  ui_story_5066_50660801_37_dialog_content = "Eso debería ser todo... ¿Lo entiendes completamente?",
  ui_story_5066_50660801_38_dialog_content = "Pensé que sería mucho más complicado que esto... ¡Pero no es tan difícil de entender!",
  ui_story_5066_50660801_39_dialog_content = "Entonces, eh... ¿Quieres un castillo grande, antiguo, mágico y que brille en la oscuridad, verdad?",
  ui_story_5066_50660801_40_dialog_content = "¿...?",
  ui_story_5066_50660801_41_dialog_content = "No tengo mucha experiencia en estas cosas... Pero por favor, créeme...",
  ui_story_5066_50660801_42_dialog_content = "Y te prometo... ¡Construiré un templo del que puedas estar orgulloso!",
  ui_story_5066_50660801_43_dialog_content = "Espero que puedas cumplir la promesa.",
  ui_story_5066_50660801_44_dialog_content = "Bien...",
  ui_story_5066_50660801_45_dialog_content = "¿Qué pasa, Connolly?",
  ui_story_5066_50660801_46_dialog_content = "Acabas de formar un pacto oficial con el Señor del Agua... Pero no pareces muy contento, ¿verdad?",
  ui_story_5066_50660801_47_dialog_content = "Bueno, me acaba de dar una misión realmente difícil...",
  ui_story_5066_50660801_48_dialog_content = "Administrar un pueblo, construir un templo... Nunca he hecho nada de esto antes...",
  ui_story_5066_50660801_49_dialog_content = "¡No hay razón para preocuparse! Simplemente no lo has intentado, ¡eso es todo!",
  ui_story_5066_50660801_50_dialog_content = "Una vez que lo intentes, descubrirás que no es tan difícil como pensabas. Siempre has tenido ese tipo de talento.",
  ui_story_5066_50660801_51_dialog_content = "No solo eso... Nosotros y los habitantes del pueblo te ayudaremos en todo lo que podamos...",
  ui_story_5066_50660801_52_dialog_content = "Si eso significa librarse del gobierno del Rey Tritón... Estoy seguro de que todos estarán emocionados por ayudar.",
  ui_story_5066_50660801_53_dialog_content = "Así es, y todo lo que necesitas hacer es cumplir con sus expectativas.",
  ui_story_5066_50660801_54_dialog_content = "¿D... De verdad?",
  ui_story_5066_50660801_55_dialog_content = "Entonces... también intentaré con todo lo que tengo...",
  ui_story_5066_50660801_56_dialog_content = "<color=#e8d9bb>Ruido sordo-</color>",
  ui_story_5066_50660801_57_dialog_content = "Su Majestad, ¡le ruego su perdón!",
  ui_story_5066_50660801_58_dialog_content = "¿Mi perdón? Mi hijo fue sometido a tanta crueldad, y...",
  ui_story_5066_50660801_59_dialog_content = "El que lo atacó; fue tu primo, ¿verdad?",
  ui_story_5066_50660801_60_dialog_content = "Bueno... ese es solo un bicho raro que nuestra familia adoptó, esencialmente... ¡no estamos relacionados!",
  ui_story_5066_50660801_61_dialog_content = "Bueno, si ese es el caso, tampoco tienes valor para mí. Guardias...",
  ui_story_5066_50660801_62_dialog_content = "¡Espera! Conozco su debilidad... Si vas a la guerra, ¡puedo garantizar tu victoria!",
  ui_story_5066_50660801_63_dialog_content = "¿...?",
  ui_story_5066_50660801_64_dialog_content = "Continúa, te escucho.",
  ui_story_5066_50660801_65_dialog_content = "Ella es... simplemente una chica normal. Es el poder del clarinete lo que la hace tan formidable.",
  ui_story_5066_50660801_66_dialog_content = "Yo... Yo, como su primo, puedo ayudarte a robar el clarinete!",
  ui_story_5066_50660801_67_dialog_content = "Entonces, los residentes del pueblo no serían más que un grupo desorganizado a tu merced.",
  ui_story_5066_50660801_68_dialog_content = "¿Estás diciendo la verdad?",
  ui_story_5066_50660801_69_dialog_content = "Absolutamente cierto, Su Majestad.",
  ui_story_5066_50660801_70_dialog_content = "Muy bien, te daré una oportunidad para hacerlo, pero si no funciona...",
  ui_story_5066_50660801_71_dialog_content = "¡Estoy dispuesto a aceptar el castigo!",
  ui_story_5066_50660901_1_dialog_content = "Uf... finalmente terminé el trabajo de hoy...",
  ui_story_5066_50660901_2_dialog_content = "Lidiar con todos los problemas de la gente... Fue suficiente para hacerme dar vueltas la cabeza...",
  ui_story_5066_50660901_3_dialog_content = "Noo-hoo... ¿Cómo se supone que debo construir un templo encima de todo esto...?",
  ui_story_5066_50660901_4_dialog_content = "Extraño mi ático... Y mi música...",
  ui_story_5066_50660901_5_dialog_content = "¡Excelente trabajo hoy, Connolly!",
  ui_story_5066_50660901_6_dialog_content = "Tú también, Dayna...",
  ui_story_5066_50660901_7_dialog_content = "Sin ti y Robyn... No sé qué haría...",
  ui_story_5066_50660901_8_dialog_content = "No seas tan humilde... En mi opinión, estás haciendo un trabajo fantástico como mensajero del Señor Aqua.",
  ui_story_5066_50660901_9_dialog_content = "Eh... ¿D-De verdad...?",
  ui_story_5066_50660901_10_dialog_content = "Pero si ustedes dos no estuvieran aquí... ni siquiera tendría el valor de hablar con la gente del pueblo...",
  ui_story_5066_50660901_11_dialog_content = "Está bien. Después de todo, todos somos buenos en cosas diferentes.",
  ui_story_5066_50660901_12_dialog_content = "Y te ayudaremos... con las cosas en las que no eres bueno...",
  ui_story_5066_50660901_13_dialog_content = "Especialmente la lucha. ¡Déjanos eso a nosotros!",
  ui_story_5066_50660901_14_dialog_content = "Entiendo... Gracias a los dos por animarme...",
  ui_story_5066_50660901_15_dialog_content = "Entonces, si no hay nada más por hoy, nos vamos ahora.",
  ui_story_5066_50660901_16_dialog_content = "Descansa mucho, Connolly... Después de todo, mañana... también debería ser bastante ocupado...",
  ui_story_5066_50660901_17_dialog_content = "Uh-huh... Lo haré.",
  ui_story_5066_50660901_18_dialog_content = "...",
  ui_story_5066_50660901_19_dialog_content = "*aturdido* Hmm...",
  ui_story_5066_50660901_20_dialog_content = "...",
  ui_story_5066_50660901_21_dialog_content = "Ah...! ¿L-Lord Aqua...?",
  ui_story_5066_50660901_22_dialog_content = "Por favor, no aparezcas detrás de mí tan de repente... Realmente me asustaste...",
  ui_story_5066_50660901_23_dialog_content = "Solo me preocupa el progreso de la construcción de mi templo.",
  ui_story_5066_50660901_24_dialog_content = "Oh... Eh... Sobre eso...",
  ui_story_5066_50660901_25_dialog_content = "No entiendo...",
  ui_story_5066_50660901_26_dialog_content = "¿Eh? ¿A qué te refieres...?",
  ui_story_5066_50660901_27_dialog_content = "Ya posees un poder absoluto e imponente.",
  ui_story_5066_50660901_28_dialog_content = "Simplemente utiliza tu poder para hacer que estos habitantes submarinos construyan mi templo y ahuyenten al enemigo por ti.",
  ui_story_5066_50660901_29_dialog_content = "Entonces, ¿por qué te preocupas tanto por sus vidas?",
  ui_story_5066_50660901_30_dialog_content = "Eh... ¿Así es como solías gobernar a la gente del fondo del mar, Señor Aqua?",
  ui_story_5066_50660901_31_dialog_content = "¿Hay algo malo con eso?",
  ui_story_5066_50660901_32_dialog_content = "Bueno, estas personas... Todos tienen sus propios pensamientos y emociones. Son seres vivos, no herramientas...",
  ui_story_5066_50660901_33_dialog_content = "La razón por la que están tan insatisfechos con el Rey Tritón en este momento es porque él también los trata como bienes prescindibles...",
  ui_story_5066_50660901_34_dialog_content = "Si los tratamos exactamente de la misma manera... No nos apoyarán de la misma forma en que nos están apoyando ahora.",
  ui_story_5066_50660901_35_dialog_content = "...",
  ui_story_5066_50660901_36_dialog_content = "Um... ¿Entiendes... lo que estoy tratando de decir?",
  ui_story_5066_50660901_37_dialog_content = "Creo en el poder absoluto, y tus palabras no pueden convencerme...",
  ui_story_5066_50660901_38_dialog_content = "Oh... Entonces, ¿cómo debería explicar...?",
  ui_story_5066_50660901_39_dialog_content = "Ah... lo tengo...",
  ui_story_5066_50660901_40_dialog_content = "Solíamos comunicarnos a través de este clarinete antes... ¿Verdad?",
  ui_story_5066_50660901_41_dialog_content = "Entonces déjame tocarte una canción llamada \"Hogar.\"",
  ui_story_5066_50660901_42_dialog_content = "Es mi canción favorita. Mi mamá me la enseñó hace mucho tiempo...",
  ui_story_5066_50660901_43_dialog_content = "Espero que te permita entender mis pensamientos un poco más claramente...",
  ui_story_5066_50660901_44_dialog_content = "Yo... lo espero con ansias.",
  ui_story_5066_50660901_45_dialog_content = "Está bien, estoy listo...",
  ui_story_5066_50660901_46_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660901_47_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660901_48_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660901_49_dialog_content = "*Toca una melodía*",
  ui_story_5066_50660901_50_dialog_content = "Ahh... La música de mamá siempre es la que más me tranquiliza...",
  ui_story_5066_50660901_51_dialog_content = "...",
  ui_story_5066_50660901_52_dialog_content = "Oh... Lo siento, creo que... me involucré demasiado.",
  ui_story_5066_50660901_53_dialog_content = "Está bien... Estoy profundamente conmovido.",
  ui_story_5066_50660901_54_dialog_content = "Ya veo. No consideras esta ciudad submarina como un lugar para gobernar, sino como... tu hogar.",
  ui_story_5066_50660901_55_dialog_content = "A pesar de enfrentar hostilidad, no guardas resentimiento porque tú, que perdiste a tus padres, has encontrado un lugar al que pertenecer.",
  ui_story_5066_50660901_56_dialog_content = "No estás luchando por tus deseos; estás luchando para proteger el pueblo que te brinda refugio.",
  ui_story_5066_50660901_57_dialog_content = "Oh... Realmente no es nada tan especial...",
  ui_story_5066_50660901_58_dialog_content = "Solo... solo creo que sería bueno si todos pudieran vivir felices en un lugar que puedan llamar suyo, eso es todo...",
  ui_story_5066_50660901_59_dialog_content = "Todos están trabajando duro para construir tu templo, así que... ¡Espero que también se sienta como un hogar para ti!",
  ui_story_5066_50660901_60_dialog_content = "...",
  ui_story_5066_50660901_61_dialog_content = "Quizás formar un pacto contigo es la elección más acertada que he tomado en mis largos años.",
  ui_story_5066_50660901_62_dialog_content = "Estaré esperando con gran anticipación el... hogar que me vas a proporcionar.",
  ui_story_5066_50660901_63_dialog_content = "Uf...",
  ui_story_5066_50660901_64_dialog_content = "Ayudar a todos a resolver sus problemas me hace sentir feliz y todo...",
  ui_story_5066_50660901_65_dialog_content = "Pero aún prefiero disfrutar de mi tiempo a solas por la noche.",
  ui_story_5066_50660901_66_dialog_content = "...",
  ui_story_5066_50660901_67_dialog_content = "¿Eh? Es tan tarde... ¿Quién podría estar buscándome a esta hora...?",
  ui_story_5066_50660901_68_dialog_content = "Hmm... Quizás debería fingir estar dormido...",
  ui_story_5066_50660901_69_dialog_content = "No, me sentiría mal si hiciera eso. Simplemente iré a echar un vistazo...",
  ui_story_5066_50660901_70_dialog_content = "<color=#e8d9bb>¡Pam—</color>",
  ui_story_5066_50660901_71_dialog_content = "¡O-Oye! No hay necesidad de ser grosero... ¡Ya voy!",
  ui_story_5066_50660901_72_dialog_content = "...",
  ui_story_5066_50660901_73_dialog_content = "¿Quién eres...? ¿Y cómo entraste aquí...?",
  ui_story_5066_50660901_74_dialog_content = "¿¡Eh?! ¿Qué está pasando...? ¿Por qué... estás sosteniendo mi clarinete en tus manos?!",
  ui_story_5066_50660901_75_dialog_content = "Tsk, me atraparon tan temprano...",
  ui_story_5066_50660901_76_dialog_content = "Como un dedicado residente del pueblo, estoy haciendo esto por tu propio bien, Queen Connolly!",
  ui_story_5066_50660901_77_dialog_content = "Puedes hablar con ese monstruo todo gracias a esta cosa, ¿eh?",
  ui_story_5066_50660901_78_dialog_content = "No es solo una cosa... ¡E-Esto es una reliquia de mi mamá! ¡Es importante para mí!",
  ui_story_5066_50660901_79_dialog_content = "No me importa si es una reliquia o no; si te dejamos descontrolarte así, ¡todo el pueblo pagará el precio!",
  ui_story_5066_50660901_80_dialog_content = "Sin embargo, si le presento esto al Rey Tritón, tú y tus seguidores no podrán causar problemas. Je-je...",
  ui_story_5066_50660901_81_dialog_content = "¡Prepárense para que el ejército del Rey Tritón aplaste esta tonta ciudad!",
  ui_story_5066_50660901_82_dialog_content = "¡E-Espera...!",
  ui_story_5066_50660901_83_dialog_content = "Por favor... ¡Devuélvemelo, por favor!",
  ui_story_5066_50660901_84_dialog_content = "Tsk, simplemente no te rindes, ¿eh?",
  ui_story_5066_50660901_85_dialog_content = "Je-je, ¡ya estoy preparado para esto!",
  ui_story_5066_50660901_86_dialog_content = "...",
  ui_story_5066_50660901_87_dialog_content = "¡Eeek!",
  ui_story_5066_50660901_88_dialog_content = "No quiero problemas, así que por favor... por favor, sal de mi camino...!",
  ui_story_5066_50660901_89_dialog_content = "¡...!",
  ui_story_5066_50660901_90_dialog_content = "Ah... No tengo más opción que pelear, pero lo juro... Juro que alcanzaré a ese ladrón...",
  ui_story_5066_50660902_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5066_50660902_2_dialog_content = "Aunque... logré perder a esos guardias...",
  ui_story_5066_50660902_3_dialog_content = "Parece que... el ladrón... ya se fue hace tiempo...",
  ui_story_5066_50660902_4_dialog_content = "Aqua Lord... ¿Sigues... ahí...?",
  ui_story_5066_50660902_5_dialog_content = "...",
  ui_story_5066_50660902_6_dialog_content = "Boo-hoo... Lo sabía. Sin el clarinete, no podemos comunicarnos entre nosotros.",
  ui_story_5066_50660902_7_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50660902_8_dialog_content = "¿Eh? ... ¿Q-Qué fue ese ruido? No me digas...",
  ui_story_5066_50660902_9_dialog_content = "¿El rey y el ladrón están trabajando juntos para atacarnos en todos los frentes...?",
  ui_story_5066_50660902_10_dialog_content = "Yo... puede que ya no pueda alcanzar al Señor del Aqua, pero...",
  ui_story_5066_50660902_11_dialog_content = "Prometí que no retrocedería...",
  ui_story_5066_50660902_12_dialog_content = "¡Su Majestad, esto es!",
  ui_story_5066_50660902_13_dialog_content = "...",
  ui_story_5066_50660902_14_dialog_content = "Nunca esperé que estallara una rebelión en un pueblo tan decaído.",
  ui_story_5066_50660902_15_dialog_content = "¡Les mostraré a estos rebeldes lo tontos que son!",
  ui_story_5066_50660902_16_dialog_content = "¡Ahora los nombro vanguardias! ¡Síganme y demostremos juntos el poder y la majestuosidad de nuestro Reino de Tritones!",
  ui_story_5066_50660902_17_dialog_content = "¡¡¡Sí!!!",
  ui_story_5066_50660902_18_dialog_content = "...",
  ui_story_5066_50660902_19_dialog_content = "¿Es ese... el Rey Tritón!?",
  ui_story_5066_50660902_20_dialog_content = "¿Está él realmente aquí... para buscar venganza por su hijo...?",
  ui_story_5066_50660902_21_dialog_content = "¡Rápido! ¡Ve e informa a Queen Connolly!",
  ui_story_5066_50660902_22_dialog_content = "Je, qué grupo de personas desaliñadas.",
  ui_story_5066_50660902_23_dialog_content = "¡Todos ustedes, humildes residentes, miren bien! ¡Soy su rey!",
  ui_story_5066_50660902_24_dialog_content = "Ahora proclamo oficialmente a Connolly y sus seguidores como rebeldes.",
  ui_story_5066_50660902_25_dialog_content = "Aquí, busco venganza por la deshonra que sufrió mi hijo y la rebelión de los habitantes del pueblo.",
  ui_story_5066_50660902_26_dialog_content = "¡Guardias, prepárense para la batalla!",
  ui_story_5066_50660902_27_dialog_content = "¡¡¡Sí!!!",
  ui_story_5066_50661001_1_dialog_content = "...",
  ui_story_5066_50661001_2_dialog_content = "Rey Tritón... aunque solías oprimirnos, ahora, ¡ya no te tenemos miedo!",
  ui_story_5066_50661001_3_dialog_content = "Con la protección de Queen Connolly, ¡no representas ninguna amenaza para nosotros!",
  ui_story_5066_50661001_4_dialog_content = "Jajajaja, Queen Connolly? ¡Qué nombre tan ridículo!",
  ui_story_5066_50661001_5_dialog_content = "Tal vez no me tengas miedo, ¡pero tengo curiosidad por ver si le tienes miedo a esto!",
  ui_story_5066_50661001_6_dialog_content = "¿Eso es... un cañón?",
  ui_story_5066_50661001_7_dialog_content = "El barril es tan grande... pero para Queen Connolly, ¡no es gran cosa!",
  ui_story_5066_50661001_8_dialog_content = "Sí, a todos, no tengan miedo; esperen a que Queen Connolly se encargue de ello!",
  ui_story_5066_50661001_9_dialog_content = "Huff... Huff... Huff...",
  ui_story_5066_50661001_10_dialog_content = "Um... Lo siento, llego tarde...",
  ui_story_5066_50661001_11_dialog_content = "Queen ¡Connolly está aquí!",
  ui_story_5066_50661001_12_dialog_content = "¡Así como enviaste a volar a ese molesto príncipe, haz volar a este arrogante rey también!",
  ui_story_5066_50661001_13_dialog_content = "¡Envíalo volando! ¡Envíalo volando! ¡Envíalo volando!",
  ui_story_5066_50661001_14_dialog_content = "Bien...",
  ui_story_5066_50661001_15_dialog_content = "Estos tentáculos aún están conmigo...",
  ui_story_5066_50661001_16_dialog_content = "Pero...",
  ui_story_5066_50661001_17_dialog_content = "¿Es esta la reina que todos esperaban? Debo decir que es toda una vista impresionante.",
  ui_story_5066_50661001_18_dialog_content = "¡Prepárense, vanguardias! ¡Fuego!",
  ui_story_5066_50661001_19_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661001_20_dialog_content = "Ugh... Yo... ¡Protegeré a todos!",
  ui_story_5066_50661001_21_dialog_content = "<color=#e8d9bb>Auge-</color>",
  ui_story_5066_50661001_22_dialog_content = "Ah, no así... Los tentáculos no están siguiendo mis órdenes...",
  ui_story_5066_50661001_23_dialog_content = "No espera... no es que no sigan. Simplemente no pueden entenderme...",
  ui_story_5066_50661001_24_dialog_content = "A este ritmo...",
  ui_story_5066_50661001_25_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661001_26_dialog_content = "Eh... ¿podría ser que el poder de Queen Connolly no pueda igualar los cañones y vanguardias del rey?",
  ui_story_5066_50661001_27_dialog_content = "Parece un poco rara. ¿Vamos a perder...?",
  ui_story_5066_50661001_28_dialog_content = "¡Guarda ese tipo de comentario! ¡No hay forma de que perdamos!",
  ui_story_5066_50661001_29_dialog_content = "En una situación como esta... Deberíamos estar ayudándola a recuperar su fuerza anterior...",
  ui_story_5066_50661001_30_dialog_content = "¡Así es, así que vamos a darle toda la cobertura que necesita!",
  ui_story_5066_50661001_31_dialog_content = "Todos... Pero yo...",
  ui_story_5066_50661001_32_dialog_content = "Sin mi clarinete... Ya no soy tan fuerte como solía ser...",
  ui_story_5066_50661001_33_dialog_content = "Pero estos tentáculos... M-Mientras sigan aquí, ¡seguiré luchando...!",
  ui_story_5066_50661102_1_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661102_2_dialog_content = "Urgh...",
  ui_story_5066_50661102_3_dialog_content = "Connolly! ¿Estás bien?!",
  ui_story_5066_50661102_4_dialog_content = "Estoy... estoy bien, es solo...",
  ui_story_5066_50661102_5_dialog_content = "El Señor Aqua... no creo que pueda resistir mucho más...",
  ui_story_5066_50661102_6_dialog_content = "<anim type=Shake>éµè Œâ...</anim>",
  ui_story_5066_50661102_7_dialog_content = "<anim type=Shake>ç·tu€¦... ï|'H>■</anim>",
  ui_story_5066_50661102_8_dialog_content = "Lo siento mucho... Pero en este momento... No puedo entender ni una palabra de lo que dices...",
  ui_story_5066_50661102_9_dialog_content = "<anim type=Agitar>ç·tuوˆگم€... â€¦â€■</anim>",
  ui_story_5066_50661102_10_dialog_content = "Oye... mira a Queen Connolly! Ella...",
  ui_story_5066_50661102_11_dialog_content = "Esos tentáculos... Se están desvaneciendo, desapareciendo...",
  ui_story_5066_50661102_12_dialog_content = "<size=45>Jajajajaja!</size>",
  ui_story_5066_50661102_13_dialog_content = "¡La supuesta nueva reina de ustedes no es más que una figura decorativa!",
  ui_story_5066_50661102_14_dialog_content = "¡Todos, a la carga! Quien pueda atraparla será generosamente recompensado.",
  ui_story_5066_50661102_15_dialog_content = "¡Alto ahí! ¡Tu oponente está aquí!",
  ui_story_5066_50661102_16_dialog_content = "No te dejaremos... acercarte a Connolly...",
  ui_story_5066_50661102_17_dialog_content = "¡Ridículo! ¿Crees que puedes detenerme?",
  ui_story_5066_50661102_18_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661102_19_dialog_content = "¡Argh! ¡Fuera de mi camino, perros sucios!",
  ui_story_5066_50661102_20_dialog_content = "Déjame a estos tipos, Dayna. Apúrate y ve a Connolly...",
  ui_story_5066_50661102_21_dialog_content = "¡Entendido!",
  ui_story_5066_50661102_22_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661102_23_dialog_content = "<size=33>Boo-hoo... No, la he vuelto a arruinar... Lo... Lo siento mucho!</size>",
  ui_story_5066_50661102_24_dialog_content = "¡Resiste, Connolly!",
  ui_story_5066_50661102_25_dialog_content = "¿Es... Eres tú, Dayna?",
  ui_story_5066_50661102_26_dialog_content = "¡Claro! No te preocupes, cubriré tu huida.",
  ui_story_5066_50661102_27_dialog_content = "¿Eh...? Pero no puedo simplemente dejar a todos atrás así...",
  ui_story_5066_50661102_28_dialog_content = "Está bien, así que déjanos esto a nosotros por ahora.",
  ui_story_5066_50661102_29_dialog_content = "Es cierto que realmente no sabemos cómo ayudarte en este momento.",
  ui_story_5066_50661102_30_dialog_content = "Pero volverás una vez que hayas recuperado tus fuerzas, ¿verdad?",
  ui_story_5066_50661102_31_dialog_content = "Yo...",
  ui_story_5066_50661102_32_dialog_content = "Hablaremos más tarde, ¡ahora vete!",
  ui_story_5066_50661102_33_dialog_content = "Boo-hoo... Haré lo que dices.",
  ui_story_5066_50661102_34_dialog_content = "<size=33><color=#e8d9bb>¡Auge—!</color></size>",
  ui_story_5066_50661102_35_dialog_content = "Todavía están peleando...",
  ui_story_5066_50661102_36_dialog_content = "Todo es tan aterrador... Sniff... Realmente estoy mejor en un lugar oscuro como este.",
  ui_story_5066_50661102_37_dialog_content = "Mientras me esconda en esta trinchera oscura y vacía, todo estará bien...",
  ui_story_5066_50661102_38_dialog_content = "Todo estará bien... ¿Verdad?",
  ui_story_5066_50661102_39_dialog_content = "Por fin... puedo dormir bien... ¿verdad?",
  ui_story_5066_50661201_1_dialog_content = "<size=45><color=#e8d9bb>¡Auge—!</color></size>",
  ui_story_5066_50661201_2_dialog_content = "Bu ju...",
  ui_story_5066_50661201_3_dialog_content = "Yo... debería estar ayudando a los demás...",
  ui_story_5066_50661201_4_dialog_content = "Pero mi cuerpo... No deja de temblar...",
  ui_story_5066_50661201_5_dialog_content = "Después de todo, no puedo controlar estos tentáculos... No como estoy ahora...",
  ui_story_5066_50661201_6_dialog_content = "Incluso si volviera, solo estaría en el camino de todos...",
  ui_story_5066_50661201_7_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5066_50661201_8_dialog_content = "Vaya... Tan cálido... ¿Es esto una corriente de agua tibia?",
  ui_story_5066_50661201_9_dialog_content = "<color=#e8d9bb>Pat—</color>",
  ui_story_5066_50661201_10_dialog_content = "¿Mmm? ¿Mi hombro...?",
  ui_story_5066_50661201_11_dialog_content = "¡Eeek! ¿A-Alguien me encontró...? Pero quien sea, no parece hostil...",
  ui_story_5066_50661201_12_dialog_content = "¿Quién... Quién podría haberme encontrado aquí y ahora de todos los lugares...?",
  ui_story_5066_50661201_13_dialog_content = "Hola, Connolly.",
  ui_story_5066_50661201_14_dialog_content = "Guau... ¡Qué bonito delfín blanco! Y sus ojos... Son tan cálidos y brillantes...",
  ui_story_5066_50661201_15_dialog_content = "¿Quién eres?",
  ui_story_5066_50661201_16_dialog_content = "No hay necesidad de temer, Connolly. Soy uno de los habitantes submarinos a los que tú y el Señor Aqua ayudaron.",
  ui_story_5066_50661201_17_dialog_content = "Oh... ¿En serio? Pero no parece que recuerde...",
  ui_story_5066_50661201_18_dialog_content = "Entiendo. Con tantos a los que has ayudado, es imposible recordarlos a todos.",
  ui_story_5066_50661201_19_dialog_content = "Lo sé... pero aún así...",
  ui_story_5066_50661201_20_dialog_content = "<size=33>No creo que pueda olvidar tan fácilmente a un delfín blanco tan amable y bonito...</size>",
  ui_story_5066_50661201_21_dialog_content = "Pero parece que te has encontrado con un pequeño problema ahora.",
  ui_story_5066_50661201_22_dialog_content = "Y es mi turno de ayudarte tanto como pueda.",
  ui_story_5066_50661201_23_dialog_content = "Yo... boo-hoo... Tienes toda la razón...",
  ui_story_5066_50661201_24_dialog_content = "Pero, ¿cómo podría... molestarte con mis problemas?",
  ui_story_5066_50661201_25_dialog_content = "¿Por qué sería una molestia? Inspirado por ti y cómo disfrutas ayudando a otros, ahora he reunido el valor para echar una mano.",
  ui_story_5066_50661201_26_dialog_content = "Además, el mundo submarino es nuestro hogar compartido, así que me gustaría hacer mi parte para protegerlo.",
  ui_story_5066_50661201_27_dialog_content = "Oh... ¿Es así...?",
  ui_story_5066_50661201_28_dialog_content = "Bueno, primero, necesitamos salir de aquí.",
  ui_story_5066_50661201_29_dialog_content = "Este lugar no es adecuado para ti en tu estado actual.",
  ui_story_5066_50661201_30_dialog_content = "Yo... lo sé, pero ¿a dónde se supone que debo ir ahora?",
  ui_story_5066_50661201_31_dialog_content = "Conozco un refugio seguro. ¿Te gustaría venir conmigo?",
  ui_story_5066_50661201_32_dialog_content = "Sí... Si no te importa...",
  ui_story_5066_50661201_33_dialog_content = "Por favor... llévame contigo...",
  ui_story_5066_50661201_34_dialog_content = "... Espera.",
  ui_story_5066_50661201_35_dialog_content = "¿Qué ocurre?",
  ui_story_5066_50661201_36_dialog_content = "¿Habrá otras personas allí también...?",
  ui_story_5066_50661201_37_dialog_content = "Sí, por supuesto. Después de todo, a todos les gusta mucho ese lugar.",
  ui_story_5066_50661201_38_dialog_content = "Oh...",
  ui_story_5066_50661201_39_dialog_content = "Dayna y los demás siguen peleando...",
  ui_story_5066_50661201_40_dialog_content = "Pero yo... No sé cómo se supone que debo ayudarles...",
  ui_story_5066_50661201_41_dialog_content = "¿La gente de ahí... no me guardará rencor por eso?",
  ui_story_5066_50661201_42_dialog_content = "No hay necesidad de preocuparse excesivamente.",
  ui_story_5066_50661201_43_dialog_content = "Quizás puedas sentirte más seguro acerca de la reputación que construiste al ayudar a los residentes en el pasado.",
  ui_story_5066_50661201_44_dialog_content = "¿Más... confiado?",
  ui_story_5066_50661201_45_dialog_content = "Pero ya no soy la reina en la que confiaban... Ahora solo soy una vergonzosa fugitiva...",
  ui_story_5066_50661201_46_dialog_content = "Aún no es demasiado tarde.",
  ui_story_5066_50661201_47_dialog_content = "Simplemente estás dando un paso atrás por ahora, y todos lo entienden perfectamente.",
  ui_story_5066_50661201_48_dialog_content = "¿No siempre los ayudabas en el pasado, tratando los asuntos de los habitantes submarinos como si fueran propios?",
  ui_story_5066_50661201_49_dialog_content = "Ahora es tu turno de buscar su ayuda.",
  ui_story_5066_50661201_50_dialog_content = "¿Soy... realmente digno de hacer eso?",
  ui_story_5066_50661201_51_dialog_content = "Por supuesto, es debido a tu amabilidad que Dayna, Robyn y todos los demás se reúnen a tu alrededor.",
  ui_story_5066_50661201_52_dialog_content = "Su sabiduría seguramente será de ayuda para resolver tus problemas.",
  ui_story_5066_50661201_53_dialog_content = "El conocimiento combinado de todos... realmente parece ser así...",
  ui_story_5066_50661201_54_dialog_content = "Aunque no sepa qué hacer, tal vez uno de ellos... tenga la respuesta.",
  ui_story_5066_50661201_55_dialog_content = "Ten fe en todos y en ti mismo.",
  ui_story_5066_50661201_56_dialog_content = "Todo lo que has hecho antes de esto no será en vano.",
  ui_story_5066_50661201_57_dialog_content = "No olvides, aún tienes que cumplir el deseo del antiguo monstruo, ¿verdad?",
  ui_story_5066_50661201_58_dialog_content = "¡Ah!",
  ui_story_5066_50661201_59_dialog_content = "Así es... Señor Aqua... Lamento mucho haberte avergonzado de esta manera...",
  ui_story_5066_50661201_60_dialog_content = "Pero ahora sé... ¡Necesito pedir la opinión de todos!",
  ui_story_5066_50661301_1_dialog_content = "<color=#e8d9bb>Tintineo, tintineo, tintineo—</color>",
  ui_story_5066_50661301_2_dialog_content = "Vaya... No tenía idea de que existiera un lugar así aquí abajo...",
  ui_story_5066_50661301_3_dialog_content = "Es tan cálido y tranquilo... Se siente como en casa.",
  ui_story_5066_50661301_4_dialog_content = "Este lugar es bastante encantador, ¿verdad?",
  ui_story_5066_50661301_5_dialog_content = "Lo es. Muchas gracias por traerme aquí...",
  ui_story_5066_50661301_6_dialog_content = "Oh... ¡Oh no! Casi quise quedarme aquí y evitar mis problemas...",
  ui_story_5066_50661301_7_dialog_content = "Aunque es tan agradable... sé que no puedo esconderme aquí para siempre.",
  ui_story_5066_50661301_8_dialog_content = "Entonces, ¿ya descubriste con qué problema quieres pedir ayuda a todos?",
  ui_story_5066_50661301_9_dialog_content = "Ah... acabo de darme cuenta... en realidad hay tanta gente aquí...",
  ui_story_5066_50661301_10_dialog_content = "Oye, ¿no es esto Connolly?",
  ui_story_5066_50661301_11_dialog_content = "Recuperamos el arrecife de coral de nuestra familia de los Tritones, ¡todo gracias a ti!",
  ui_story_5066_50661301_12_dialog_content = "¡A nuestros niños les encantas! ¿Cuándo te resulta conveniente darles otra clase de música?",
  ui_story_5066_50661301_13_dialog_content = "¿Es así... realmente como todos me ven...?",
  ui_story_5066_50661301_14_dialog_content = "De hecho, la bondad une a las personas.",
  ui_story_5066_50661301_15_dialog_content = "Entonces, por eso debería... confiar también en las buenas intenciones de todos...",
  ui_story_5066_50661301_16_dialog_content = "¡Yo... yo entiendo ahora!",
  ui_story_5066_50661301_17_dialog_content = "Um... ¿Podría molestarlos a todos por solo unos minutos de su tiempo?",
  ui_story_5066_50661301_18_dialog_content = "Adelante. Podemos ver que parece que has encontrado algunos problemas.",
  ui_story_5066_50661301_19_dialog_content = "Si hay algo en lo que podamos ayudar, ¡no dudes en decírnoslo!",
  ui_story_5066_50661301_20_dialog_content = "Y si hay más...",
  ui_story_5066_50661301_21_dialog_content = "Boo-hoo, no me di cuenta de que todos estarían tan dispuestos a ayudar...",
  ui_story_5066_50661301_22_dialog_content = "Ejem. Bueno, amigos, realmente aprecio su entusiasmo.",
  ui_story_5066_50661301_23_dialog_content = "Pero por favor, uno a la vez, o si no Connolly no podrá escuchar a nadie.",
  ui_story_5066_50661301_24_dialog_content = "Oh... Gracias, Delfín Blanco.",
  ui_story_5066_50661301_25_dialog_content = "<size=33>Sin ti... No sé qué haría...</size>",
  ui_story_5066_50661301_26_dialog_content = "Yo... Um, me gustaría pedir la opinión de todos sobre un cierto asunto...",
  ui_story_5066_50661301_27_dialog_content = "Hace algún tiempo... Un malvado ladrón robó mi clarinete, y así perdí mi capacidad de comunicarme con el Señor del Agua...",
  ui_story_5066_50661301_28_dialog_content = "¿Alguien tiene alguna idea... sobre cómo puedo restablecer mi conexión con el Señor del Agua?",
  ui_story_5066_50661301_29_dialog_content = "...",
  ui_story_5066_50661301_30_dialog_content = "¡T-tengo una sugerencia!",
  ui_story_5066_50661301_31_dialog_content = "Por favor, adelante.",
  ui_story_5066_50661301_32_dialog_content = "En las historias legendarias que escuché cuando era joven, ¡el poder del Señor del Agua está estrechamente vinculado al templo!",
  ui_story_5066_50661301_33_dialog_content = "¡Esto tiene que ser una pista crucial! Además, Connolly, ¿no mencionaste el templo antes?",
  ui_story_5066_50661301_34_dialog_content = "Si puedes encontrar este antiguo templo, ¡recuperarás tu poder sin duda!",
  ui_story_5066_50661301_35_dialog_content = "Connolly, ¿qué opinas de esto?",
  ui_story_5066_50661301_36_dialog_content = "Creo que... haces un buen punto...",
  ui_story_5066_50661301_37_dialog_content = "Pero podría regresar demasiado tarde si busco su antiguo templo ahora mismo. Además...",
  ui_story_5066_50661301_38_dialog_content = "El Señor Aqua me confió la construcción de un nuevo templo, pero después de trabajar tanto para construirlo... El Rey Tritón lo capturó para sí mismo.",
  ui_story_5066_50661301_39_dialog_content = "Snif... Todo es mi culpa...",
  ui_story_5066_50661301_40_dialog_content = "Mantén la esperanza, Connolly. ¿Ves? ¡Los residentes ya tienen una nueva idea!",
  ui_story_5066_50661301_41_dialog_content = "¿Eh...? Está bien... ¡Por favor comparte tus pensamientos conmigo!",
  ui_story_5066_50661301_42_dialog_content = "Creo que el clarinete es solo un tipo de instrumento musical.",
  ui_story_5066_50661301_43_dialog_content = "Ya que no hay clarinete, ¿podemos usar otros instrumentos en su lugar?",
  ui_story_5066_50661301_44_dialog_content = "Tal vez al Señor Aqua no le importe mucho el timbre, ¿sabes?",
  ui_story_5066_50661301_45_dialog_content = "¿No... exigente?",
  ui_story_5066_50661301_46_dialog_content = "¿Se te ocurre algo?",
  ui_story_5066_50661301_47_dialog_content = "Pero... Todo este tiempo, creí que su poder residía en el instrumento que mi mamá me dejó...",
  ui_story_5066_50661301_48_dialog_content = "¿Es realmente posible comunicarse con el Señor del Agua sin su clarinete...?",
  ui_story_5066_50661301_49_dialog_content = "Creo que es posible.",
  ui_story_5066_50661301_50_dialog_content = "Eh...?!",
  ui_story_5066_50661301_51_dialog_content = "Creo que la capacidad de comunicarse con el Señor del Agua podría ser un poder innato propio tuyo.",
  ui_story_5066_50661301_52_dialog_content = "¿Mi propio poder...? Pero... ¿Cómo podría ser eso...?",
  ui_story_5066_50661301_53_dialog_content = "Pero piénsalo: antes de hacer el pacto, ¿no tenías ya la habilidad de comunicarte con el Aqua Lord a través de la música?",
  ui_story_5066_50661301_54_dialog_content = "Además, incluso sin el clarinete, esos tentáculos no han desaparecido; simplemente están menos receptivos.",
  ui_story_5066_50661301_55_dialog_content = "Entonces, podría no ser solo sobre el clarinete; lo que realmente importa podría ser tu música, ¿verdad?",
  ui_story_5066_50661301_56_dialog_content = "¿Mi... música?",
  ui_story_5066_50661301_57_dialog_content = "Así es. Intenta reflexionar sobre tus batallas pasadas.",
  ui_story_5066_50661301_58_dialog_content = "Y piensa en qué exactamente te dio la fuerza...",
  ui_story_5066_50661302_1_dialog_content = "*Toca una melodía*",
  ui_story_5066_50661302_2_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50661302_3_dialog_content = "...",
  ui_story_5066_50661302_4_dialog_content = "*Toca una melodía*",
  ui_story_5066_50661302_5_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50661302_6_dialog_content = "¡Eek...!",
  ui_story_5066_50661302_7_dialog_content = "...",
  ui_story_5066_50661302_8_dialog_content = "Yo... ahora recuerdo...",
  ui_story_5066_50661302_9_dialog_content = "Mi mamá dijo una vez que el poder de la música no está en los instrumentos, sino en la música misma...",
  ui_story_5066_50661302_10_dialog_content = "Estaba tan ocupado apreciando el clarinete que ella me dejó que olvidé todo acerca de lo que me enseñó...",
  ui_story_5066_50661302_11_dialog_content = "Pero ahora lo recuerdas, ¿verdad?",
  ui_story_5066_50661302_12_dialog_content = "Sí. Entonces ahora... Si puedo encontrar la pieza de música adecuada, tal vez pueda invocar al Señor del Agua de nuevo...",
  ui_story_5066_50661302_13_dialog_content = "Al igual que... cuando lo invoqué por primera vez en el ático.",
  ui_story_5066_50661302_14_dialog_content = "¿Aún recuerdas la partitura que tocaste en aquel entonces?",
  ui_story_5066_50661302_15_dialog_content = "Lo hago... Se llama \"La forma del agua\"...",
  ui_story_5066_50661302_16_dialog_content = "Pero...",
  ui_story_5066_50661302_17_dialog_content = "¿Qué, ya no puedes tocar esa partitura?",
  ui_story_5066_50661302_18_dialog_content = "Sí... la partitura todavía está en el ático de mi tía...",
  ui_story_5066_50661302_19_dialog_content = "Pero en este momento... Todo el pueblo está bajo el control del Rey Tritón.",
  ui_story_5066_50661302_20_dialog_content = "Solo lo he tocado unas pocas veces, y esta pieza musical es realmente compleja...",
  ui_story_5066_50661302_21_dialog_content = "Lo que probablemente significa... No podré convocar al Señor del Agua...",
  ui_story_5066_50661302_22_dialog_content = "No te estreses demasiado. Todavía tenemos muchas opciones.",
  ui_story_5066_50661302_23_dialog_content = "También puedes pensar si hay alguna composición que podría despertar el interés del Señor del Agua, ¿quizás?",
  ui_story_5066_50661302_24_dialog_content = "Ah... ¡Aquí está! Es una canción llamada <color=#FFB400>Hogar</color>!",
  ui_story_5066_50661302_25_dialog_content = "¿Hogar?",
  ui_story_5066_50661302_26_dialog_content = "¡Sí! Es una canción maravillosa... Una que mi mamá me enseñó.",
  ui_story_5066_50661302_27_dialog_content = "También es la canción que toqué... ¡Cuando el Señor Aqua y yo finalmente comenzamos a entendernos!",
  ui_story_5066_50661302_28_dialog_content = "¡Creo que es esto! ¡Esta canción tiene que funcionar!",
  ui_story_5066_50661302_29_dialog_content = "Mmm... creo que sí, pero...",
  ui_story_5066_50661302_30_dialog_content = "No puedo hacer promesas, así que... ¿podrías acompañarme al templo... y ayudarme a invocar al Señor del Agua?",
  ui_story_5066_50661302_31_dialog_content = "Descansa tranquilo, estaré justo a tu lado.",
  ui_story_5066_50661302_32_dialog_content = "Además, todos allá todavía te están esperando.",
  ui_story_5066_50661302_33_dialog_content = "Espérenme, todos...",
  ui_story_5066_50661302_34_dialog_content = "Esto es para todos ustedes...",
  ui_story_5066_50661302_35_dialog_content = "Si no tengo mi clarinete, simplemente usaré otro instrumento. Si no puedo tocar La Forma del Agua, entonces encontraré otra canción para tocar. Pase lo que pase... definitivamente...",
  ui_story_5066_50661302_36_dialog_content = "¡Definitivamente me comunicaré con el Señor Aqua de nuevo!",
  ui_story_5066_50661401_1_dialog_content = "Huff... Huff... Finalmente nos estamos acercando...",
  ui_story_5066_50661401_2_dialog_content = "Gracias por quedarte conmigo todo este tiempo, Delfín Blanco... Si no fuera por ti...",
  ui_story_5066_50661401_3_dialog_content = "Estos son todos tus propios poderes; mi parte es bastante insignificante.",
  ui_story_5066_50661401_4_dialog_content = "Y el momento en que necesitas mostrar tus verdaderos poderes aún está por llegar.",
  ui_story_5066_50661401_5_dialog_content = "Oh... P-Pero siempre estarás ahí para ayudarme, ¿verdad?",
  ui_story_5066_50661401_6_dialog_content = "Por supuesto, estaré contigo en cada paso del camino.",
  ui_story_5066_50661401_7_dialog_content = "Oye, vamos a ver quién es esta pequeña niña desaliñada, ¿no?",
  ui_story_5066_50661401_8_dialog_content = "¿Eh...? ¿No eres...?",
  ui_story_5066_50661401_9_dialog_content = "Vaya, ¿no es este Queen Connolly? Hace tiempo que no te veo, ¿y ya te has convertido en un desastre?",
  ui_story_5066_50661401_10_dialog_content = "¿Prima...?",
  ui_story_5066_50661401_11_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_5066_50661401_12_dialog_content = "Magnífico debut, ¿verdad? Celoso, ¿no? ¡Este fue un regalo del propio Rey Tritón!",
  ui_story_5066_50661401_13_dialog_content = "Después de todo, fui el mayor héroe de esta batalla; ¡ahora soy todo un personaje importante frente al Rey Tritón!",
  ui_story_5066_50661401_14_dialog_content = "Y tú, mi pobre e inútil primo... si tan solo me hubieras escuchado en aquel entonces y te hubieras convertido en el coleccionable del Príncipe Tritón.",
  ui_story_5066_50661401_15_dialog_content = "¡Nunca terminarías en una situación tan miserable! Jajaja...",
  ui_story_5066_50661401_16_dialog_content = "¿Mayor contribuyente...?",
  ui_story_5066_50661401_17_dialog_content = "(Pero... ¡Mi primo nunca ha tenido ningún talento real del que hablar! ¿Cómo podría ser el \"mayor contribuyente\" en la campaña del rey...?)",
  ui_story_5066_50661401_18_dialog_content = "(¿Podría ser?!)",
  ui_story_5066_50661401_19_dialog_content = "Fuiste tú... Tú fuiste quien robó mi clarinete, ¿verdad?!",
  ui_story_5066_50661401_20_dialog_content = "Oh... ¿Así que solo te diste cuenta ahora? ¿No es un poco tarde y tonto, querido primo?",
  ui_story_5066_50661401_21_dialog_content = "Pero incluso si te has dado cuenta, ¿qué puedes hacer ahora?",
  ui_story_5066_50661401_22_dialog_content = "¿Tienes alguna forma de vengarte de mí? ¡Lo dudo!",
  ui_story_5066_50661401_23_dialog_content = "Por favor... Devuélvemelo...",
  ui_story_5066_50661401_24_dialog_content = "¿Qué dijiste? Tú...",
  ui_story_5066_50661401_25_dialog_content = "Dije por favor devuélveme mi clarinete...!",
  ui_story_5066_50661401_26_dialog_content = "Solo palabras vacías...",
  ui_story_5066_50661401_27_dialog_content = "Soy muy consciente de que, sin ese clarinete, ¡no vales absolutamente nada!",
  ui_story_5066_50661401_28_dialog_content = "¿Yo...? Es cierto que no hay nada especial en mí...",
  ui_story_5066_50661401_29_dialog_content = "¡Pero el verdadero poder... reside en la música!",
  ui_story_5066_50661401_30_dialog_content = "Poder... Qué broma...",
  ui_story_5066_50661401_31_dialog_content = "Incluso sin mi clarinete, puedo usar mi voz...",
  ui_story_5066_50661401_32_dialog_content = "Y incluso sin mis partituras... Sus melodías y emociones fueron grabadas en mi corazón hace mucho tiempo.",
  ui_story_5066_50661401_33_dialog_content = "¡Ahora mismo, todo lo que necesito hacer es cantar!",
  ui_story_5066_50661401_34_dialog_content = "*canta*",
  ui_story_5066_50661401_35_dialog_content = "<color=#e8d9bb>Como una princesa regresando a su castillo, Connolly canta mientras sube las escaleras en espiral, usando su voz para invocar al Señor del Agua...</color>",
  ui_story_5066_50661401_36_dialog_content = "<color=#e8d9bb>Al mismo tiempo, finalmente expresa los sentimientos que guardó en su corazón durante tanto tiempo.</color>",
  ui_story_5066_50661401_37_dialog_content = "¡Cállate! Deja de cantar... ¡Para! ¡Aléjate de mí!",
  ui_story_5066_50661401_38_dialog_content = "¡Solo un lugar donde todos se unen puede llamarse hogar!♪",
  ui_story_5066_50661401_39_dialog_content = "¡Un castillo vacío, por más grandioso que sea, siempre se sentirá solo!♪",
  ui_story_5066_50661401_40_dialog_content = "¡Así que por favor escucha mi llamada y regresa a mi lado!♪",
  ui_story_5066_50661401_41_dialog_content = "Porque aquí está tu hogar, ¡donde no necesitas esconderte!♪",
  ui_story_5066_50661401_42_dialog_content = "<color=#e8d9bb>Mientras su voz resuena, varios peces y partículas de Lumina comienzan a reunirse alrededor de Connolly, como si se unieran a ella en la oración por un milagro...</color>",
  ui_story_5066_50661401_43_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5066_50661401_44_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5066_50661401_45_dialog_content = "...",
  ui_story_5066_50661401_46_dialog_content = "Señor Aqua... Estoy tan feliz de verte de nuevo...",
  ui_story_5066_50661401_47_dialog_content = "...",
  ui_story_5066_50661401_48_dialog_content = "Lo siento mucho... Arruiné todo...",
  ui_story_5066_50661401_49_dialog_content = "Debes estar tan decepcionado... por haber hecho un pacto con alguien tan vergonzoso e inútil como yo... ¿verdad?",
  ui_story_5066_50661401_50_dialog_content = "Tal vez ya no tengo derecho a decir que estamos unidos... Y quizás sea descarado de mi parte preguntar... ¡Pero lo voy a hacer de todos modos!",
  ui_story_5066_50661401_51_dialog_content = "¡Ahora mismo... realmente, realmente necesito tu ayuda!",
  ui_story_5066_50661401_52_dialog_content = "Entonces, ¿puedes por favor... prestarme tu poder una vez más?!",
  ui_story_5066_50661401_53_dialog_content = "...",
  ui_story_5066_50661401_54_dialog_content = "No detesto tu actitud actual.",
  ui_story_5066_50661401_55_dialog_content = "No todos estos accidentes son tu culpa.",
  ui_story_5066_50661401_56_dialog_content = "Al menos tus intenciones me han llegado.",
  ui_story_5066_50661401_57_dialog_content = "Entonces, ¿eso significa...?!",
  ui_story_5066_50661401_58_dialog_content = "Pero ahora... no puedo ayudarte...",
  ui_story_5066_50661401_59_dialog_content = "Oh... lo sabía... pero entiendo...",
  ui_story_5066_50661401_60_dialog_content = "No me malinterpretes.",
  ui_story_5066_50661401_61_dialog_content = "El médium se perdió y el pacto se rompió prematuramente. He perdido mi forma física en este mundo.",
  ui_story_5066_50661401_62_dialog_content = "Ahora, si deseas obtener mi poder, debes ir al templo...",
  ui_story_5066_50661401_63_dialog_content = "Bueno, para ser precisos, debes ir a ese extravagante castillo que has construido para mí y extraer todo el poder restante.",
  ui_story_5066_50661401_64_dialog_content = "Pero...",
  ui_story_5066_50661401_65_dialog_content = "Um... ¿Hay algún tipo de truco...?",
  ui_story_5066_50661401_66_dialog_content = "Pero si quieres aprovechar al máximo ese poder, tendrás que heredar el templo y convertirte en la verdadera Aqua Queen.",
  ui_story_5066_50661401_67_dialog_content = "El verdadero... Aqua Queen...?",
  ui_story_5066_50661401_68_dialog_content = "¿Estás diciendo... que ahora mismo soy solo un impostor?",
  ui_story_5066_50661401_69_dialog_content = "No eres un impostor. Lo que pasa es que, si solo buscas protegerte a ti mismo, ya has llegado bastante lejos.",
  ui_story_5066_50661401_70_dialog_content = "Mi presencia residual es suficiente para protegerte.",
  ui_story_5066_50661401_71_dialog_content = "Sin embargo, si tu objetivo es proteger el pueblo, mi presencia residual se queda muy corta en poder.",
  ui_story_5066_50661401_72_dialog_content = "Necesitarás abrazar más poder y... asumir más responsabilidad.",
  ui_story_5066_50661401_73_dialog_content = "Deberás dar un paso adelante, desde las sombras hasta el centro de atención, hacia la oscuridad donde incluso mi poder no puede protegerte...",
  ui_story_5066_50661401_74_dialog_content = "Jejejeje...",
  ui_story_5066_50661401_75_dialog_content = "¿Qué? ¿Te parecen divertidas mis palabras?",
  ui_story_5066_50661401_76_dialog_content = "Es solo que, por primera vez... Pareces un poco denso...",
  ui_story_5066_50661401_77_dialog_content = "Por qué dices eso...?",
  ui_story_5066_50661401_78_dialog_content = "¿No estuvieron claros mis sentimientos en mi canción hace un momento? Además...",
  ui_story_5066_50661401_79_dialog_content = "Ahora que el Delfín Blanco me está ayudando, junto con todos los demás...",
  ui_story_5066_50661401_80_dialog_content = "Por supuesto, elegiría seguir adelante.",
  ui_story_5066_50661401_81_dialog_content = "Parece que tal vez te subestimé esta vez...",
  ui_story_5066_50661401_82_dialog_content = "Entonces, muéstrame el poder de tu determinación.",
  ui_story_5066_50661401_83_dialog_content = "Lo haré... Y te prometo que no te decepcionaré de nuevo...",
  ui_story_5066_50661401_84_dialog_content = "Ahora, querido primo... ¿Me devolverías mi clarinete, por favor?",
  ui_story_5066_50661401_85_dialog_content = "O... ¿preferirías sentir toda la fuerza de mi ira por lo que has hecho...?",
  ui_story_5066_50661401_86_dialog_content = "Tsk...",
  ui_story_5066_50661401_87_dialog_content = "(Su poder aún no se ha recuperado por completo. ¡Mientras pueda detenerla aquí, seguirá siendo una chica normal!)",
  ui_story_5066_50661401_88_dialog_content = "Jeje, vamos, primo...",
  ui_story_5066_50661401_89_dialog_content = "Sirviendo al Rey Pescador, mi fuerza ha aumentado mucho más de lo que puedas imaginar.",
  ui_story_5066_50661401_90_dialog_content = "Y esta vez, voy a darlo todo, ¡el tipo de todo que acabará con tu miserable vida! ¡Dale!",
  ui_story_5066_50661402_1_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50661402_2_dialog_content = "*canta*",
  ui_story_5066_50661402_3_dialog_content = "¡Aghhh! ¡Ay, ay...! ¡Ya basta! Connolly, detente. ¡Soy tu primo!",
  ui_story_5066_50661402_4_dialog_content = "¿El clarinete, dices? Está bien, yo... te lo devolveré...",
  ui_story_5066_50661402_5_dialog_content = "Por favor... ¡por favor no me mates! Te lo suplico...",
  ui_story_5066_50661402_6_dialog_content = "No harías algo tan cruel e injusto, ¿verdad? Tu tía y tío estarían devastados, ya sabes, ¡devastados!",
  ui_story_5066_50661402_7_dialog_content = "¡Así es, todavía te están esperando en casa!",
  ui_story_5066_50661402_8_dialog_content = "Casa...",
  ui_story_5066_50661402_9_dialog_content = "Exactamente, hogar, ¡nuestro hogar! Vamos a casa para estar con nuestras familias, ¡los que realmente nos aman!",
  ui_story_5066_50661402_10_dialog_content = "...",
  ui_story_5066_50661402_11_dialog_content = "Aunque estoy agradecido con mi tía y tío por acogerme después de perderlo todo...",
  ui_story_5066_50661402_12_dialog_content = "Ese lugar ya no es mi hogar...",
  ui_story_5066_50661402_13_dialog_content = "Además, tú eras el que quería llevarme lejos de su casa... ¿No es cierto, primo?!",
  ui_story_5066_50661402_14_dialog_content = "Y ahora también quieres destruir las casas de estas personas... No te equivoques, ahora eres mi enemigo.",
  ui_story_5066_50661402_15_dialog_content = "¡Ay! No... es solo un gran malentendido, tú... ¡por favor no me mates!",
  ui_story_5066_50661402_16_dialog_content = "Yo... nunca mataría a nadie... Tú y yo no somos iguales...",
  ui_story_5066_50661402_17_dialog_content = "Entonces vete... sal de este pueblo ahora mismo... ¡Y nunca regreses!",
  ui_story_5066_50661402_18_dialog_content = "Está bien, entiendo. Solo déjame ir; nunca volveré y nunca me volverás a ver...",
  ui_story_5066_50661402_19_dialog_content = "...",
  ui_story_5066_50661402_20_dialog_content = "No debería estar molestando a mi primo ahora mismo...",
  ui_story_5066_50661402_21_dialog_content = "El Rey Tritón ya ha ocupado la mayoría de esta área. Y no solo eso...",
  ui_story_5066_50661402_22_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661402_23_dialog_content = "El sonido de los cañonazos se está acercando. De hecho, parece que viene directamente hacia mí...",
  ui_story_5066_50661402_24_dialog_content = "¡Pero esta vez estoy listo para ello!",
  ui_story_5066_50661402_25_dialog_content = "Dayna, Robyn, todos... ¡Por favor, cuídense!",
  ui_story_5066_50661501_1_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661501_2_dialog_content = "¡Argh! ¿No me digas que también tenemos que renunciar a esta posición?!",
  ui_story_5066_50661501_3_dialog_content = "No hay fin a todos estos malditos guardias tritones.",
  ui_story_5066_50661501_4_dialog_content = "Dayna... Deberíamos retirarnos por ahora...",
  ui_story_5066_50661501_5_dialog_content = "Pero si nos retiramos ahora, solo pondremos a Connolly en más peligro.",
  ui_story_5066_50661501_6_dialog_content = "Puedes seguir adelante, ¿verdad Robyn?",
  ui_story_5066_50661501_7_dialog_content = "Si es por Connolly... puedo aguantar un poco más.",
  ui_story_5066_50661501_8_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50661501_9_dialog_content = "¿Eran... tentáculos?!",
  ui_story_5066_50661501_10_dialog_content = "Es Connolly... ella ha vuelto...",
  ui_story_5066_50661501_11_dialog_content = "Eh... L-lo siento por hacer esperar a todos...!",
  ui_story_5066_50661501_12_dialog_content = "\"¿Hacernos esperar\"? ¡Deja de ser tan educado con nosotros ya!",
  ui_story_5066_50661501_13_dialog_content = "Ver que estás bien... es la mejor noticia que podríamos recibir...",
  ui_story_5066_50661501_14_dialog_content = "¿Entonces recuperaste tus poderes?",
  ui_story_5066_50661501_15_dialog_content = "No, parece que... Se ha vuelto aún más fuerte...",
  ui_story_5066_50661501_16_dialog_content = "¡Perfecto! Entonces, limpiemos el suelo con estos tontos y hagámoslos correr, Connolly!",
  ui_story_5066_50661501_17_dialog_content = "¡E-Entendido! ¡Lo daré todo!",
  ui_story_5066_50661501_18_dialog_content = "<color=#e8d9bb>Clang—Crujido—</color>",
  ui_story_5066_50661501_19_dialog_content = "<color=#e8d9bb>Whoosh, whoosh, whoosh—¡Zas!</color>",
  ui_story_5066_50661501_20_dialog_content = "¡Vaya, pensé que ustedes iban a ser más fuertes que esto!",
  ui_story_5066_50661501_21_dialog_content = "¿¡Ni siquiera uno solo de ustedes puede pelear?!",
  ui_story_5066_50661501_22_dialog_content = "<color=#e8d9bb>Clang—Crujido—</color>",
  ui_story_5066_50661501_23_dialog_content = "Connolly... La fuerza que tienes ahora... Estoy tan aliviado...",
  ui_story_5066_50661501_24_dialog_content = "Sí... Y todo es porque ustedes me dieron tanto tiempo. Muchas, muchas gracias...",
  ui_story_5066_50661501_25_dialog_content = "No hace falta agradecernos, especialmente cuando aún queda mucha lucha por hacer.",
  ui_story_5066_50661501_26_dialog_content = "<color=#e8d9bb>Clang—Crujido—</color>",
  ui_story_5066_50661501_27_dialog_content = "...",
  ui_story_5066_50661501_28_dialog_content = "¡Basta de pececillos! ¡Saquen ya a ese rey arrogante de ustedes!",
  ui_story_5066_50661501_29_dialog_content = "Robyn, ve a ayudar a Connolly.",
  ui_story_5066_50661501_30_dialog_content = "Rogelio...",
  ui_story_5066_50661501_31_dialog_content = "Parece que este es el verdadero poder del Aqua Queen.",
  ui_story_5066_50661501_32_dialog_content = "Interesante. Realmente es algo increíble.",
  ui_story_5066_50661501_33_dialog_content = "Pero, ¿de verdad todos creen que estoy en desventaja ahora?",
  ui_story_5066_50661501_34_dialog_content = "Tú... Sea lo que sea que estés tramando, yo... ¡No te dejaré salirte con la tuya!",
  ui_story_5066_50661501_35_dialog_content = "Jajajaja, ¿detenerme? ¡Tengo toda la información sobre ti!",
  ui_story_5066_50661501_36_dialog_content = "Entonces, todo el poder del Señor Aqua proviene de ese hogar que has construido, ese castillo, ¿no es así?",
  ui_story_5066_50661501_37_dialog_content = "Traeré más balas de cañón desde las aguas poco profundas y volaré el castillo por completo. ¡Que el poder del Señor Aqua se disperse por completo!",
  ui_story_5066_50661501_38_dialog_content = "¿Y te llamas rey, luchando así? Eres despreciable, pero al menos tienes el valor de decirlo por fin.",
  ui_story_5066_50661501_39_dialog_content = "Je, ¿tienes un problema con eso? ¿Qué puedes hacer?",
  ui_story_5066_50661501_40_dialog_content = "Connolly, si juras lealtad a mí ahora, quizás deje vivir a ti y a ese monstruo.",
  ui_story_5066_50661501_41_dialog_content = "Haz tu elección rápido; no quiero perder más tiempo contigo.",
  ui_story_5066_50661501_42_dialog_content = "Yo... le prometí al Señor Aqua que protegería su hogar... Y también el hogar de todos los demás.",
  ui_story_5066_50661501_43_dialog_content = "Esta es mi obligación... ¡Y no huiré de ella nunca más!",
  ui_story_5066_50661501_44_dialog_content = "Si realmente estás dispuesto a explotar el templo...",
  ui_story_5066_50661501_45_dialog_content = "Entonces, con mi autoridad como el Aqua Queen... ¡Para defender esta ciudad, declaro la guerra en tu contra!",
  ui_story_5066_50661501_46_dialog_content = "Excelente, es hora de poner fin a la farsa de ustedes rebeldes.",
  ui_story_5066_50661501_47_dialog_content = "¡Todas las unidades! ¡A mi comando! ¡Lancen un ataque a gran escala en el pueblo!",
  ui_story_5066_50661501_48_dialog_content = "¡No perdones a ninguno de los rebeldes en la ciudad!",
  ui_story_5066_50661501_49_dialog_content = "...",
  ui_story_5066_50661501_50_dialog_content = "...",
  ui_story_5066_50661501_51_dialog_content = "...",
  ui_story_5066_50661501_52_dialog_content = "<size=50>¡Ohhhhhh!</size>",
  ui_story_5066_50661601_1_dialog_content = "*Toca una melodía*",
  ui_story_5066_50661601_2_dialog_content = "<color=#e8d9bb>¡Golpe—Golpe!</color>",
  ui_story_5066_50661601_3_dialog_content = "Urgh...",
  ui_story_5066_50661601_4_dialog_content = "Urgh...",
  ui_story_5066_50661601_5_dialog_content = "...",
  ui_story_5066_50661601_6_dialog_content = "Parece que la información de ese bromista estaba equivocada...",
  ui_story_5066_50661601_7_dialog_content = "El poder proviene de la música en sí, ¡no de ese clarinete!",
  ui_story_5066_50661601_8_dialog_content = "Pero así, je, ¡las cosas se volvieron demasiado fáciles!",
  ui_story_5066_50661601_9_dialog_content = "¡A mi orden!",
  ui_story_5066_50661601_10_dialog_content = "¡...!",
  ui_story_5066_50661601_11_dialog_content = "Haz ruido lo más fuerte posible para interferir con la música del Aqua Queen!",
  ui_story_5066_50661601_12_dialog_content = "¡Sí!",
  ui_story_5066_50661601_13_dialog_content = "¡Arghhhh! ¡Cierren sus estúpidas bocas, todos ustedes!",
  ui_story_5066_50661601_14_dialog_content = "¡No podemos dejar que esos idiotas sigan haciendo tanto ruido! ¡Vamos, Robyn!",
  ui_story_5066_50661601_15_dialog_content = "Entendido... Tenemos que detenerlos...",
  ui_story_5066_50661601_16_dialog_content = "<color=#e8d9bb>¡Clang—Wham—!</color>",
  ui_story_5066_50661601_17_dialog_content = "¡Más fuerte, hazlo más fuerte! ¡Que resuene!",
  ui_story_5066_50661601_18_dialog_content = "Urgh... ¡Son tan ruidosos! Apenas puedo escuchar mi propia voz...",
  ui_story_5066_50661601_19_dialog_content = "A este ritmo... No me digas que volverá a suceder...",
  ui_story_5066_50661601_20_dialog_content = "No hay que temer, Connolly.",
  ui_story_5066_50661601_21_dialog_content = "El Delfín Blanco... ¿Viniste a ayudarme de nuevo?",
  ui_story_5066_50661601_22_dialog_content = "Yo... sé que no debería desanimarme tan fácilmente, pero... ¿cómo se supone que toque mi canción ahora...?",
  ui_story_5066_50661601_23_dialog_content = "Solo sé tú mismo.",
  ui_story_5066_50661601_24_dialog_content = "¿Solo... ser yo mismo...?",
  ui_story_5066_50661601_25_dialog_content = "Así es. Tu actuación no está destinada para la batalla, ¿verdad?",
  ui_story_5066_50661601_26_dialog_content = "¿Cuál es el propósito de tu música?",
  ui_story_5066_50661601_27_dialog_content = "El significado de mi música...",
  ui_story_5066_50661601_28_dialog_content = "Aun así, no estoy completamente descontento...",
  ui_story_5066_50661601_29_dialog_content = "Y eso es porque... ¡Todavía tengo mi música! Todavía tengo el instrumento y las partituras que mi mamá me dejó...",
  ui_story_5066_50661601_30_dialog_content = "<color=#e8d9bb>Cuando Connolly se siente sola, toca esas melodías familiares.</color>",
  ui_story_5066_50661601_31_dialog_content = "<color=#e8d9bb>Una marcha alegre en La Mayor, una balada lírica en Si Menor y una sombría sonata en Do Mayor. Estas canciones no son solo sus amigos, sino su salvación.</color>",
  ui_story_5066_50661601_32_dialog_content = "Yo... Ahora entiendo.",
  ui_story_5066_50661601_33_dialog_content = "Siempre estaba solo cuando tocaba mi música. Era mi forma de salvarme a mí mismo...",
  ui_story_5066_50661601_34_dialog_content = "Esa alegría irremplazable de tocar música me pertenece solo a mí y a nadie más... También es lo que mejor sé hacer...",
  ui_story_5066_50661601_35_dialog_content = "¡Lo que significa que todavía puedo hacerlo!",
  ui_story_5066_50661601_36_dialog_content = "*Toca una melodía*",
  ui_story_5066_50661601_37_dialog_content = "Ruido, ¿dónde está el ruido que haces?! ¡Debes ser más ruidoso que esa maldita música!",
  ui_story_5066_50661601_38_dialog_content = "*Toca una melodía*",
  ui_story_5066_50661601_39_dialog_content = "Uh-oh, el Rey Tritón se ve realmente enojado ahora!",
  ui_story_5066_50661601_40_dialog_content = "Ahora es el momento... De cambiar las mareas de la batalla...",
  ui_story_5066_50661701_1_dialog_content = "<color=#e8d9bb>¡Bang—Bang—!</color>",
  ui_story_5066_50661701_2_dialog_content = "¡Vamos, pandilla de monstruos con cara de pez! ¡Dame un verdadero desafío!",
  ui_story_5066_50661701_3_dialog_content = "Desde que Connolly regresó, la batalla se ha vuelto mucho más fácil... Qué alivio...",
  ui_story_5066_50661701_4_dialog_content = "Estos guardias inútiles; no son confiables en momentos críticos en absoluto...",
  ui_story_5066_50661701_5_dialog_content = "Pero ustedes rebeldes, no sean engreídos tan temprano.",
  ui_story_5066_50661701_6_dialog_content = "Como rey, no tenía la intención de pelear en persona.",
  ui_story_5066_50661701_7_dialog_content = "Pero con cosas como esta ahora...",
  ui_story_5066_50661701_8_dialog_content = "...!?",
  ui_story_5066_50661701_9_dialog_content = "Su Majestad, no tiene que...",
  ui_story_5066_50661701_10_dialog_content = "¡Cállate! Dile a todos que cesen sus ataques sin sentido y redirijan todo el poder de fuego hacia el castillo.",
  ui_story_5066_50661701_11_dialog_content = "¡Estoy cubriendo el bombardeo personalmente!",
  ui_story_5066_50661701_12_dialog_content = "Hoy borraremos este pueblo del mapa, comenzando con ese maldito castillo.",
  ui_story_5066_50661701_13_dialog_content = "Pero de esta manera, incluso si ganamos esta batalla, no obtendremos nada...",
  ui_story_5066_50661701_14_dialog_content = "¡Cállense, inútiles! ¡Hagan lo que digo!",
  ui_story_5066_50661701_15_dialog_content = "¡¡¡Sí!!!",
  ui_story_5066_50661701_16_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661701_17_dialog_content = "¡Esa explosión del cañón parecía aún más poderosa que antes!",
  ui_story_5066_50661701_18_dialog_content = "¿Está... tratando de nivelar todo el pueblo...?",
  ui_story_5066_50661701_19_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661701_20_dialog_content = "¡Y parece que están concentrando el fuego en el propio templo!",
  ui_story_5066_50661701_21_dialog_content = "A este ritmo... El templo se reducirá a escombros en poco tiempo...",
  ui_story_5066_50661701_22_dialog_content = "No... ¡No puedo dejar que destruya el templo!",
  ui_story_5066_50661701_23_dialog_content = "Esto es... El hogar del Señor Aqua... ¡Y todos trabajaron tan duro para construirlo!",
  ui_story_5066_50661701_24_dialog_content = "No podemos... ¡No dejaremos que el Rey Tritón lo derribe!",
  ui_story_5066_50661701_25_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—Whoosh—</color>",
  ui_story_5066_50661701_26_dialog_content = "<color=#e8d9bb>Con todas sus fuerzas, Connolly bloquea cada disparo de cañón entrante con sus tentáculos.</color>",
  ui_story_5066_50661701_27_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661701_28_dialog_content = "Connolly¡¡¡",
  ui_story_5066_50661701_29_dialog_content = "¡Te vas a lastimar si sigues así!",
  ui_story_5066_50661701_30_dialog_content = "Pero el templo... No puedo permitirlo...",
  ui_story_5066_50661701_31_dialog_content = "...",
  ui_story_5066_50661701_32_dialog_content = "Está bien, Connolly, no hay problema.",
  ui_story_5066_50661701_33_dialog_content = "¿Eh... Eres tú, Aqua Lord...?",
  ui_story_5066_50661701_34_dialog_content = "Tu determinación y emociones me son totalmente claras.",
  ui_story_5066_50661701_35_dialog_content = "Protegeré la ciudad. Así que puedes enfrentarte con todo al Rey Tritón.",
  ui_story_5066_50661701_36_dialog_content = "Pero...",
  ui_story_5066_50661701_37_dialog_content = "No hay \"peros\". Connolly, ya te he dicho que ser una verdadera reina conlleva más responsabilidades...",
  ui_story_5066_50661701_38_dialog_content = "Pero nuestro pacto... Y tu hogar...",
  ui_story_5066_50661701_39_dialog_content = "Casa... Ajajajajajaja...",
  ui_story_5066_50661701_40_dialog_content = "Esta vez, eres tú quien no lo entiende.",
  ui_story_5066_50661701_41_dialog_content = "¿Yo...?",
  ui_story_5066_50661701_42_dialog_content = "Me has contado durante mucho tiempo a través de tus canciones el verdadero significado de hogar. ¿No lo recuerdas?",
  ui_story_5066_50661701_43_dialog_content = "El pueblo es el hogar de todos los residentes submarinos, y son los habitantes del pueblo y tú juntos quienes me construyeron un nuevo hogar...",
  ui_story_5066_50661701_44_dialog_content = "Mientras el pueblo siga en pie, el hogar que deseo siempre se podrá reconstruir, tarde o temprano.",
  ui_story_5066_50661701_45_dialog_content = "Señor Aqua...",
  ui_story_5066_50661701_46_dialog_content = "Vete ahora. Esta vez, déjame unirme a ti... para proteger nuestro querido pueblo, nuestro más preciado... ¡hogar!",
  ui_story_5066_50661702_1_dialog_content = "<color=#e8d9bb>Whoosh—Golpe—</color>",
  ui_story_5066_50661702_2_dialog_content = "Ughhh...",
  ui_story_5066_50661702_3_dialog_content = "<color=#e8d9bb>¡Whoosh—Bofetada—!</color>",
  ui_story_5066_50661702_4_dialog_content = "Haa... Haa... Por fin ha terminado...",
  ui_story_5066_50661702_5_dialog_content = "Rayos...",
  ui_story_5066_50661702_6_dialog_content = "Yo... el poderoso Rey Tritón... no puedo creer que... perdí contra alguien como tú...",
  ui_story_5066_50661702_7_dialog_content = "Jejejeje... ¡No, aún no he perdido! ¡Esto no ha terminado!",
  ui_story_5066_50661702_8_dialog_content = "Connolly, ¡escucha!",
  ui_story_5066_50661702_9_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661702_10_dialog_content = "El bombardeo aún no ha terminado, ¡pero ya no tienes el poder para detenerlo!",
  ui_story_5066_50661702_11_dialog_content = "¡La victoria será mía! ¡MÍA!",
  ui_story_5066_50661702_12_dialog_content = "Jajajaja... ¡Larga vida al Reino de los Tritones!",
  ui_story_5066_50661702_13_dialog_content = "El pueblo... todos...",
  ui_story_5066_50661702_14_dialog_content = "Yo... Puede que esté completamente agotado ahora, pero... ¡No estoy solo en esta lucha!",
  ui_story_5066_50661702_15_dialog_content = "<color=#e8d9bb>Auge-!</color>",
  ui_story_5066_50661702_16_dialog_content = "Aaahhhh—",
  ui_story_5066_50661702_17_dialog_content = "No importa cuán fuerte sea tu fanfarronería, ¡no opacará el sonido de los cañones!",
  ui_story_5066_50661702_18_dialog_content = "¡Soy el ganador! ¡Es mi victoria!",
  ui_story_5066_50661702_19_dialog_content = "<color=#e8d9bb>Bajo una lluvia de fuego de cañón, el cuerpo de Connolly se balancea impotente como un alga marina.</color>",
  ui_story_5066_50661702_20_dialog_content = "<color=#e8d9bb>Al mirar hacia arriba, ve algo flotando lejos en la superficie del agua. Un resplandor cálido y familiar...</color>",
  ui_story_5066_50661702_21_dialog_content = "Señor Aqua...",
  ui_story_5066_50661702_22_dialog_content = "Yo... derroté al Rey Tritón, tal como dije que lo haría... ¡Cumplí con mis deberes!",
  ui_story_5066_50661702_23_dialog_content = "Pero tu cuerpo... ¿Qué le pasó?!",
  ui_story_5066_50661702_24_dialog_content = "Lo has hecho bien...",
  ui_story_5066_50661702_25_dialog_content = "Pero para proteger la ciudad... necesitarás un poder aún más avanzado, el poder del verdadero Aqua Queen...",
  ui_story_5066_50661702_26_dialog_content = "Ahora... te traspaso este poder a ti.",
  ui_story_5066_50661702_27_dialog_content = "No... ¡Espera, Señor Aqua! Esto no es lo que acordamos...!",
  ui_story_5066_50661702_28_dialog_content = "¿No deberíamos... No deberíamos defender esta ciudad juntos?!",
  ui_story_5066_50661702_29_dialog_content = "De hecho, tú... heredarás todo mi poder...",
  ui_story_5066_50661702_30_dialog_content = "Y estaré contigo siempre, cuidando la ciudad...",
  ui_story_5066_50661702_31_dialog_content = "Cuidando... nuestro hogar.",
  ui_story_5066_50661702_32_dialog_content = "Espera, Señor Aqua... por favor, no desaparezcas... no me dejes completamente solo...",
  ui_story_5066_50661702_33_dialog_content = "Por siempre, tú... no estarás solo...",
  ui_story_5066_50661702_34_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5066_50661702_35_dialog_content = "Aqua... Señor...",
  ui_story_5066_50661702_36_dialog_content = "Este poder... se siente tan cálido...",
  ui_story_5066_50661702_37_dialog_content = "Esto es... El poder completo del Señor Aqua... que me transmitió...",
  ui_story_5066_50661702_38_dialog_content = "¡Pero ahora no es el momento de lamentarse...!",
  ui_story_5066_50661702_39_dialog_content = "La voluntad y los deseos del Señor Aqua... ¡Ahora son míos!",
  ui_story_5066_50661702_40_dialog_content = "Hmph... ¡nada más que faroles!",
  ui_story_5066_50661702_41_dialog_content = "La verdad es que ese monstruo no pudo resistir mi bombardeo... y desapareció. ¿No es obvio?",
  ui_story_5066_50661702_42_dialog_content = "El cañón no dejará de disparar, y tú...",
  ui_story_5066_50661702_43_dialog_content = "<color=#e8d9bb>Connolly no habla, pero en cambio levanta suavemente su clarinete.</color>",
  ui_story_5066_50661702_44_dialog_content = "Tú... ya has llegado a tal punto, ¿qué más puedes hacer?!",
  ui_story_5066_50661702_45_dialog_content = "Esta canción de cuna está dedicada a ti, así como al resto de tus soldados violentos y desalmados.",
  ui_story_5066_50661702_46_dialog_content = "Tu sueño de aplastar esta ciudad ha terminado. Ahora es el momento... de enviarte a un nuevo sueño.",
  ui_story_5066_50661702_47_dialog_content = "¡Por favor, disfrútalo mientras te enviamos de vuelta a los Bajíos!",
  ui_story_5066_50661702_48_dialog_content = "*Toca una melodía*",
  ui_story_5066_50661702_49_dialog_content = "<color=#e8d9bb>Connolly toca una pieza tierna y conmovedora, llena del poder de la amistad, el recuerdo y su firme determinación.</color>",
  ui_story_5066_50661702_50_dialog_content = "<color=#e8d9bb>Todos los enemigos, incluido el Rey Tritón, caen en un sueño profundo mientras Connolly realiza una actuación perfecta...</color>",
  ui_story_5066_50661702_51_dialog_content = "No puedo creerlo. ¡Una sola canción fue suficiente para convertir a esos tritones sedientos de sangre en un grupo de peces somnolientos!",
  ui_story_5066_50661702_52_dialog_content = "¡Levántate, aliento de cebo! ¡Aún no hemos terminado de luchar!",
  ui_story_5066_50661702_53_dialog_content = "Entonces este es el poder de Connolly... Pero parece que también ocurrió algo malo...",
  ui_story_5066_50661702_54_dialog_content = "Si lo se.",
  ui_story_5066_50661702_55_dialog_content = "El Señor Aqua se ha ido, ¿verdad?",
  ui_story_5066_50661702_56_dialog_content = "Por eso deberíamos estar consolándola en este momento en lugar de quedarnos aquí parados...",
  ui_story_5066_50661702_57_dialog_content = "¡Entendido! ¡Vamos a salir!",
  ui_story_5066_50661702_58_dialog_content = "¿Es... es realmente todo esto terminado esta vez?",
  ui_story_5066_50661702_59_dialog_content = "Hiciste un trabajo fantástico, Connolly.",
  ui_story_5066_50661702_60_dialog_content = "P-Por favor, no me alabes. Debería estar agradeciéndote por guiarme todo este tiempo...",
  ui_story_5066_50661702_61_dialog_content = "Solo un poco de ayuda de mi parte. Debo decir que tu apariencia mientras cantabas esa canción de cuna hace un momento fue elegante y llena de gracia.",
  ui_story_5066_50661702_62_dialog_content = "Aaahhhh... T-Tú te estás burlando de mí, ¿verdad?!",
  ui_story_5066_50661702_63_dialog_content = "Está bien, tus amigos llegarán justo a tiempo; ¡celebremos todos juntos esta victoria!",
  ui_story_5066_50661702_64_dialog_content = "¡Oye, Connolly! ¡Por aquí!",
  ui_story_5066_50661702_65_dialog_content = "Miren, ¡reunimos a todos los tritones dormidos en un solo lugar!",
  ui_story_5066_50661702_66_dialog_content = "Son realmente viscosos... Fue mucho más trabajo de lo que pensaba...",
  ui_story_5066_50661702_67_dialog_content = "El Rey Tritón tiene una cabeza bastante grande, ¿crees que podemos meterlo ahí?",
  ui_story_5066_50661702_68_dialog_content = "Creo... ¡Encajará perfectamente!",
  ui_story_5066_50661702_69_dialog_content = "¡Muy bien, aquí va!",
  ui_story_5066_50661702_70_dialog_content = "Atacar un pueblo indefenso con cañones y explosivos... Apuesto a que incluso un tirano como él nunca lo pensó...",
  ui_story_5066_50661702_71_dialog_content = "Que algún día también lo lanzarían de un cañón, ¿eh?",
  ui_story_5066_50661702_72_dialog_content = "La verdad, estoy emocionado por ver cómo va...",
  ui_story_5066_50661702_73_dialog_content = "Yo... simplemente creo que esta es la mejor manera de sacarlos a todos de aquí...",
  ui_story_5066_50661702_74_dialog_content = "Este pequeño pueblo finalmente conocerá la paz y la seguridad después de esto...",
  ui_story_5066_50661702_75_dialog_content = "¿Podrías encender la mecha ya, Connolly? ¡Me muero por ver esto explotar!",
  ui_story_5066_50661702_76_dialog_content = "Vale, claro...",
  ui_story_5066_50661702_77_dialog_content = "Tres, dos, uno—¡Fuego!",
  ui_story_5066_50661702_78_dialog_content = "<size=45><color=#e8d9bb>¡Auge—!</color></size>",
  ui_story_5066_50661702_79_dialog_content = "Um... ¿Es así como todo debería terminar, Delfín Blanco...?",
  ui_story_5066_50661702_80_dialog_content = "Por supuesto. No hay un final mejor que este.",
  ui_story_5066_50661702_81_dialog_content = "A todos ustedes, feos tritones, espero que disfruten de este sueño dentro de un sueño.",
  ui_story_5066_50661801_1_dialog_content = "Uf... Por fin todo ha terminado...",
  ui_story_5066_50661801_2_dialog_content = "Todo esto se sintió como un sueño extraño...",
  ui_story_5066_50661801_3_dialog_content = "Quizás... Si pudiera dormirme como el resto de esos peces...",
  ui_story_5066_50661801_4_dialog_content = "¿Podría... ver al Señor Aqua una vez más?",
  ui_story_5066_50661801_5_dialog_content = "Hey Connolly, estas personas dicen que sus hogares fueron destruidos en la batalla. ¿No deberíamos encontrar una manera de darles refugio por ahora?",
  ui_story_5066_50661801_6_dialog_content = "Y este niño dice que se separó de su mamá... Pero no te preocupes, lo ayudaré a buscar...",
  ui_story_5066_50661801_7_dialog_content = "Ahh, lo siento por eso...",
  ui_story_5066_50661801_8_dialog_content = "Ahora no es el momento de sumergirme en mi tristeza...",
  ui_story_5066_50661801_9_dialog_content = "Prometí que me convertiría en un verdadero Aqua Queen... Y me niego a huir de mis deberes nunca más...",
  ui_story_5066_50661801_10_dialog_content = "Dayna! Robyn! Ya voy...",
  ui_story_5066_50661801_11_dialog_content = "<color=#e8d9bb>¡Chasquido—Chasquido—Chasquido—</color>",
  ui_story_5066_50661801_12_dialog_content = "¡¿Eh?!",
  ui_story_5066_50661801_13_dialog_content = "¿Son estos... tentáculos de agua? Pero son tan pequeños...",
  ui_story_5066_50661801_14_dialog_content = "Aqua Lord... ¿Sigues aquí?! Nunca me dejaste, ¿verdad...?",
  ui_story_5066_50661801_15_dialog_content = "¿Señor Aqua? Pero... ¿no eres tú el verdadero Señor Aqua?!",
  ui_story_5066_50661801_16_dialog_content = "¿Eh...? ¿Y-Yo?!",
  ui_story_5066_50661801_17_dialog_content = "Así es, somos tus sirvientes... y tus amigos...",
  ui_story_5066_50661801_18_dialog_content = "¡Hemos venido a estar contigo para que no te sientas solo!",
  ui_story_5066_50661801_19_dialog_content = "¿Me haces compañía...?",
  ui_story_5066_50661801_20_dialog_content = "De hecho, tú... heredarás todo mi poder...",
  ui_story_5066_50661801_21_dialog_content = "Y estaré contigo siempre, cuidando la ciudad...",
  ui_story_5066_50661801_22_dialog_content = "Cuidando... nuestro hogar.",
  ui_story_5066_50661801_23_dialog_content = "Por siempre, tú... no estarás solo...",
  ui_story_5066_50661801_24_dialog_content = "(Entonces esto significa... El Señor Aqua no desapareció por completo...)",
  ui_story_5066_50661801_25_dialog_content = "(En cambio, volvió... ¡Como tres entidades diferentes!)",
  ui_story_5066_50661801_26_dialog_content = "Eh... ¿De dónde exactamente... vinieron ustedes tres...?",
  ui_story_5066_50661801_27_dialog_content = "¡Venimos de otra dimensión!",
  ui_story_5066_50661801_28_dialog_content = "¡La dimensión de la ilusión!",
  ui_story_5066_50661801_29_dialog_content = "¡La dimensión de la imaginación!",
  ui_story_5066_50661801_30_dialog_content = "¡La dimensión de la música!",
  ui_story_5066_50661801_31_dialog_content = "Y hay... ¿Tres de ustedes?",
  ui_story_5066_50661801_32_dialog_content = "Cuando hablas, suena como una marcha, una balada y una sonata tocando al mismo tiempo.",
  ui_story_5066_50661801_33_dialog_content = "Lo siento, tengo un poco de dificultad para distinguir entre los tres...",
  ui_story_5066_50661801_34_dialog_content = "¡Estoy tocando marchas! ¡El tono más poderoso!",
  ui_story_5066_50661801_35_dialog_content = "Estoy tocando baladas, las suaves melodías en tono menor.",
  ui_story_5066_50661801_36_dialog_content = "Estoy tocando una sonata, sencilla pero profunda, en la clave mayor más profunda y amplia.",
  ui_story_5066_50661801_37_dialog_content = "Oh, poderosa Aqua Queen, ¿puedes distinguirnos ahora?",
  ui_story_5066_50661801_38_dialog_content = "¡Ahora puedo distinguirlos perfectamente! ¡Cada uno de ustedes tiene una voz hermosa también!",
  ui_story_5066_50661801_39_dialog_content = "Pero aún así, ¿por qué renaciste como tres seres diferentes...?",
  ui_story_5066_50661801_40_dialog_content = "Es incómodo para el noble Señor Aqua admitirlo, ¡pero solo tiene un asistente! ¡Tener tres aumenta la majestuosidad!",
  ui_story_5066_50661801_41_dialog_content = "Con solo un amigo, a veces podrías sentirte solo, pero con tres, ese no será el caso.",
  ui_story_5066_50661801_42_dialog_content = "Tener un acompañante no es suficiente para una familia sólida, pero tres son suficientes para enfrentar la dificultad.",
  ui_story_5066_50661801_43_dialog_content = "Connolly¡A partir de hoy, dejemos que seamos nosotros quienes te acompañemos!"
}
return config
